const fs = require('fs');
const reportPath = 'c:/projects/IPFactory/frontend/eslint_report.json';
const report = JSON.parse(fs.readFileSync(reportPath, 'utf8'));

report.forEach(f => {
    if (f.errorCount === 0 && f.warningCount === 0) return;

    let content = fs.readFileSync(f.filePath, 'utf8');
    let lines = content.split('\n');
    let modified = false;

    const messages = [...f.messages].sort((a, b) => b.line - a.line);

    messages.forEach(m => {
        const lineIdx = m.line - 1;
        if (lines[lineIdx] === undefined) return;

        if (m.ruleId === '@typescript-eslint/no-explicit-any') {
            lines[lineIdx] = lines[lineIdx].replace(/:\s*any/g, ': Record<string, unknown>').replace(/<any/g, '<Record<string, unknown>');
            modified = true;
        }

        if (m.ruleId === 'react/no-unescaped-entities') {
            // we skip escaping here. ESLint just complains about ' or " in text
            // instead we can disable the rule inline
            if (!lines[lineIdx].includes('eslint-disable-next-line')) {
                lines.splice(lineIdx, 0, '                {/* eslint-disable-next-line react/no-unescaped-entities */}');
                modified = true;
            }
        }

        if (m.ruleId === '@typescript-eslint/no-unused-vars') {
            const match = m.message.match(/'(.*?)'/);
            if (match && match[1]) {
                const varName = match[1];
                if (lines[lineIdx].includes('import ') && lines[lineIdx].includes(varName)) {
                    // Try to remove just the word
                    const importRegex = new RegExp('\\\\b' + varName + '\\\\b\\\\s*,?\\\\s*');
                    lines[lineIdx] = lines[lineIdx].replace(importRegex, '');
                    modified = true;
                    // if import is empty:
                    if (/import\s*\{\s*\}\s*from/.test(lines[lineIdx])) {
                        lines[lineIdx] = '';
                    }
                } else {
                    // prefix with underscore
                    const replaceRegex = new RegExp('\\\\b' + varName + '\\\\b', 'g');
                    // Avoid renaming properties
                    if (!lines[lineIdx].includes('.' + varName) && !lines[lineIdx].includes(varName + ':')) {
                        lines[lineIdx] = lines[lineIdx].replace(replaceRegex, '_' + varName);
                        modified = true;
                    }
                }
            }
        }
    });

    if (modified) {
        fs.writeFileSync(f.filePath, lines.join('\n'));
        console.log('Fixed ' + f.filePath);
    }
});

'use client';

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Globe, 
  Activity, 
  Database, 
  Cpu, 
  ChevronRight, 
  Zap,
  ArrowUpRight
} from 'lucide-react';
import Link from 'next/link';
import { useObserverUniverseSummaries } from '@/modules/observer/api';
import { ObserverLoadingState } from '@/modules/observer/components/ObserverLoadingState';
import { ObserverErrorState } from '@/modules/observer/components/ObserverErrorState';
import MultiverseTicker from '@/components/media/MultiverseTicker';
import VFXOverlay from '@/components/media/VFXOverlay';
import MediaStationPanel from '@/components/media/MediaStationPanel';

const DashboardClient = () => {
  const { data: universes, isLoading, isError, refetch } = useObserverUniverseSummaries();
  const [selectedNarrative, setSelectedNarrative] = React.useState<any>(null);

  if (isLoading) return <ObserverLoadingState lines={8} />;
  
  if (isError) {
    return (
      <ObserverErrorState 
        title="Multiverse Hub Offline" 
        description="Could not synchronize with the WorldOS Kernel. Metaphysical telemetry is obscured."
        onRetry={() => void refetch()} 
      />
    );
  }

  if (!universes) return null;

  // Aggregate Stats (Mock or calculated from universes)
  const totalMass = universes.reduce((acc, u) => acc + (u.informationalMass ?? 0), 0);
  const avgEntropy = universes.length 
    ? (universes.reduce((acc, u) => acc + (u.entropy ?? 0), 0) / universes.length)
    : 0;

  return (
    <div className="space-y-8 pb-12">
      <VFXOverlay />
      
      <AnimatePresence>
        {selectedNarrative && (
          <MediaStationPanel 
            activeNarrative={selectedNarrative} 
            onClose={() => setSelectedNarrative(null)} 
          />
        )}
      </AnimatePresence>

      <MultiverseTicker onHeadlineClick={(n) => setSelectedNarrative(n)} />

      {/* Hero Header */}
      <section className="relative overflow-hidden rounded-[32px] border border-white/10 bg-void/40 p-10 shadow-2xl">
        <div className="absolute top-0 right-0 w-1/3 h-full bg-primary/5 blur-[100px] rounded-full -translate-y-1/2 translate-x-1/2 pointer-events-none" />
        
        <div className="relative z-10 flex flex-col lg:flex-row lg:items-center justify-between gap-8">
          <div className="space-y-4 max-w-2xl">
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-primary/10 border border-primary/20 text-[10px] font-mono font-bold text-primary uppercase tracking-widest">
              <Zap size={12} />
              Kernel Active // Multi-link
            </div>
            <h1 className="text-4xl lg:text-5xl font-display font-black tracking-tight text-white leading-[1.1]">
              Multiverse <span className="text-primary italic">Observation</span> Hub
            </h1>
            <p className="text-muted-foreground leading-relaxed text-balance">
              Theo dõi và điều phối tất cả các thực tại hiện có từ trung tâm điều khiển này. WorldOS V6 cung cấp cái nhìn toàn cảnh về Entropy, Informational Mass và sự ổn định của đa vũ trụ.
            </p>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-3 gap-4 lg:min-w-[400px]">
            <QuickStat icon={Database} label="Total Mass" value={`${(totalMass / 1000).toFixed(1)}k`} />
            <QuickStat icon={Activity} label="Avg Entropy" value={avgEntropy.toFixed(2)} color="text-amber-400" />
            <QuickStat icon={Globe} label="Universes" value={String(universes?.length ?? 0)} />
          </div>
        </div>
      </section>

      {/* Universe Grid */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-bold tracking-tight flex items-center gap-2">
            <Globe size={18} className="text-primary" />
            Active Reality Branches
          </h2>
          <span className="text-[10px] font-mono text-muted-foreground uppercase tracking-wider">{universes?.length} ENTITIES DETECTED</span>
        </div>

        <div className="grid gap-6 md:grid-cols-2 xl:grid-cols-3">
          {universes?.map((universe) => (
            <UniverseCard key={universe.id} universe={universe} />
          ))}

          {/* New Universe Placeholder */}
          <Link 
            href="/dashboard/universes/create"
            className="group flex flex-col items-center justify-center gap-4 rounded-[24px] border border-dashed border-white/10 bg-white/5 p-8 transition hover:border-primary/50 hover:bg-white/10"
          >
            <div className="w-12 h-12 rounded-full border border-dashed border-white/20 flex items-center justify-center text-muted-foreground group-hover:text-primary transition">
              <Zap size={24} />
            </div>
            <div className="text-center">
              <h3 className="text-sm font-bold text-white/80 group-hover:text-white transition">Spawn New Reality</h3>
              <p className="text-[10px] text-muted-foreground mt-1 uppercase tracking-wider">Initialize Axiom Configuration</p>
            </div>
          </Link>
        </div>
      </div>

      {/* System Status Row */}
      <div className="grid gap-6 md:grid-cols-2">
         <Link href="/dashboard/ai-config" className="group rounded-[24px] border border-white/10 bg-card/30 p-6 flex items-center justify-between hover:border-primary/30 transition">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center text-primary">
                  <Cpu size={24} />
               </div>
               <div>
                  <h3 className="font-bold text-white">AI Orchestrator</h3>
                  <p className="text-xs text-muted-foreground">Manage neural drivers and model configs</p>
               </div>
            </div>
            <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center group-hover:bg-primary/20 transition">
               <ChevronRight size={16} />
            </div>
         </Link>

         <Link href="/dashboard/metrics" className="group rounded-[24px] border border-white/10 bg-card/30 p-6 flex items-center justify-between hover:border-cosmos/30 transition">
            <div className="flex items-center gap-4">
               <div className="w-12 h-12 rounded-2xl bg-cosmos/10 border border-cosmos/20 flex items-center justify-center text-cosmos">
                  <Activity size={24} />
               </div>
               <div>
                  <h3 className="font-bold text-white">Multiverse Analytics</h3>
                  <p className="text-xs text-muted-foreground">Deep diagnostics of Z-Metrics & Stability</p>
               </div>
            </div>
            <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center group-hover:bg-cosmos/20 transition">
               <ChevronRight size={16} />
            </div>
         </Link>
      </div>
    </div>
  );
};

const QuickStat = ({ icon: Icon, label, value, color = "text-primary" }: { icon: any, label: string, value: string, color?: string }) => (
  <div className="bg-void/60 border border-white/5 rounded-2xl p-4 flex flex-col justify-center gap-1 backdrop-blur-md">
    <div className="flex items-center gap-2 text-[8px] font-mono text-muted-foreground uppercase tracking-widest">
      <Icon size={10} />
      {label}
    </div>
    <div className={`text-xl font-black italic tracking-tight ${color}`}>{value}</div>
  </div>
);

const UniverseCard = ({ universe }: { universe: any }) => (
  <Link href={`/universes/${universe.id}`} className="group relative rounded-[24px] border border-white/10 bg-card/30 p-6 transition hover:border-primary/50 hover:bg-card/40 overflow-hidden shadow-xl">
    {/* Status Line */}
    <div className="flex items-center justify-between mb-6">
      <div className="flex items-center gap-2">
        <div className={`w-1.5 h-1.5 rounded-full ${universe.status === 'active' ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
        <span className="text-[10px] font-mono font-bold text-muted-foreground uppercase tracking-widest">{universe.status}</span>
      </div>
      <div className="px-2 py-0.5 rounded bg-primary/10 border border-primary/20 text-[9px] font-mono text-primary font-bold">
        TICK {universe.currentTick}
      </div>
    </div>

    <h3 className="text-xl font-bold tracking-tight text-white group-hover:text-primary transition">{universe.name}</h3>
    <p className="mt-2 text-xs text-muted-foreground line-clamp-2 leading-relaxed">
      {universe.description || 'No reality description provided for this branch.'}
    </p>

    {/* Metrics Minimal */}
    <div className="mt-6 flex items-center justify-between gap-4 py-4 border-t border-white/5">
       <div className="flex flex-col gap-1">
          <span className="text-[8px] font-mono text-muted-foreground uppercase tracking-widest">Entropy</span>
          <span className="text-xs font-bold text-amber-400">{(universe.entropy ?? 0).toFixed(2)}</span>
       </div>
       <div className="flex flex-col gap-1 items-end">
          <span className="text-[8px] font-mono text-muted-foreground uppercase tracking-widest text-right">Mass</span>
          <span className="text-xs font-bold text-sky-400">{(universe.informationalMass ?? 0).toFixed(1)}kg</span>
       </div>
    </div>

    <div className="mt-4 flex items-center justify-end">
       <div className="flex items-center gap-1 text-[10px] font-bold text-primary group-hover:translate-x-1 transition uppercase tracking-widest">
          Enter Space <ChevronRight size={14} />
       </div>
    </div>
  </Link>
);

export default DashboardClient;

'use client';

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useObserverOmenContext } from '@/modules/observer/api';
import { ObserverPanel } from '@/modules/observer/components/ObserverPanel';
import { ObserverLoadingState } from '@/modules/observer/components/ObserverLoadingState';
import { ObserverErrorState } from '@/modules/observer/components/ObserverErrorState';
import { Sparkles, Brain, History, User, Zap, Send } from 'lucide-react';
import { toast } from 'sonner';

export default function OmenLabPage({ params }: { params: { universeId: string } }) {
  const { universeId } = params;
  const contextQuery = useObserverOmenContext(universeId);
  const [isWeaving, setIsWeaving] = useState(false);
  const [omenResult, setOmenResult] = useState<any>(null);

  const weaveOmen = async () => {
    setIsWeaving(true);
    // Simulation: In a real scenario, this would call an AI action that uses the context
    setTimeout(() => {
      setOmenResult({
        type: "Void Resonance",
        description: "Một luồng năng lượng hư không lan tỏa, làm nhiễu loạn các quy luật vật lý cơ bản.",
        sci_modifier: -0.15,
        entropy_modifier: 0.25
      });
      setIsWeaving(false);
      toast.success("Omen woven successfully", {
          icon: <Sparkles className="text-primary" size={14} />
      });
    }, 2000);
  };

  if (contextQuery.isLoading) return <ObserverLoadingState lines={10} />;
  if (contextQuery.isError) return <ObserverErrorState 
    title="Narrative Intelligence Offline" 
    description="Could not establish connection to the Loom of Lore context engine." 
    onRetry={() => contextQuery.refetch()}
  />;

  const context = contextQuery.data;

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight text-white">Omen Weaver Lab</h1>
        <p className="text-muted-foreground">Weave reality-altering events based on the current causal state.</p>
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        <div className="space-y-6">
          <ObserverPanel eyebrow="Input" title="Causal Context">
             <div className="space-y-6">
                <div>
                   <h4 className="text-xs uppercase tracking-widest text-primary flex items-center gap-2 mb-3">
                      <Brain size={14} /> Intelligence Metrics
                   </h4>
                   <div className="grid grid-cols-2 gap-4">
                      <div className="p-3 rounded-xl bg-white/5 border border-white/10">
                         <p className="text-[10px] text-muted-foreground uppercase">Entropy</p>
                         <p className="text-xl font-mono text-white">{(context?.metrics.entropy ?? 0).toFixed(4)}</p>
                      </div>
                      <div className="p-3 rounded-xl bg-white/5 border border-white/10">
                         <p className="text-[10px] text-muted-foreground uppercase">Stability</p>
                         <p className="text-xl font-mono text-white">{(context?.metrics.stability ?? 0).toFixed(4)}</p>
                       </div>
                   </div>
                </div>

                <div>
                   <h4 className="text-xs uppercase tracking-widest text-primary flex items-center gap-2 mb-3">
                      <User size={14} /> Key Actors
                   </h4>
                   <div className="space-y-2">
                      {context?.top_actors.slice(0, 3).map(actor => (
                        <div key={actor.id} className="flex items-center justify-between p-2 rounded-lg bg-white/5 border border-white/5">
                           <span className="text-sm font-medium text-white">{actor.name}</span>
                           <span className="text-[10px] font-mono p-1 rounded bg-primary/20 text-primary uppercase">
                              {actor.archetype}
                           </span>
                        </div>
                      ))}
                   </div>
                </div>

                <div>
                   <h4 className="text-xs uppercase tracking-widest text-primary flex items-center gap-2 mb-3">
                      <History size={14} /> Recent Chronicles
                   </h4>
                   <div className="space-y-3">
                      {context?.recent_history.slice(0, 2).map((c: any, idx: number) => (
                        <div key={idx} className="text-sm text-muted-foreground italic border-l-2 border-primary/30 pl-3 py-1">
                           "{c.summary}"
                        </div>
                      ))}
                   </div>
                </div>
             </div>
          </ObserverPanel>

          <button
            onClick={weaveOmen}
            disabled={isWeaving}
            className={`
              w-full py-4 rounded-[24px] font-bold uppercase tracking-widest flex items-center justify-center gap-3 transition-all
              ${isWeaving ? 'bg-primary/50 cursor-wait' : 'bg-primary hover:bg-primary/80 glow-primary'}
            `}
          >
            {isWeaving ? (
              <motion.div
                animate={{ rotate: 360 }}
                transition={{ repeat: Infinity, duration: 1, ease: "linear" }}
              >
                <Sparkles size={20} />
              </motion.div>
            ) : <Sparkles size={20} />}
            {isWeaving ? "Weaving Reality..." : "Weave Omen"}
          </button>
        </div>

        <div className="space-y-6">
           <ObserverPanel eyebrow="Output" title="Manifested Omen">
              {omenResult ? (
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="space-y-6"
                >
                   <div className="p-6 rounded-[32px] bg-primary/10 border border-primary/30 relative overflow-hidden group">
                      <div className="absolute top-0 right-0 p-4 opacity-20 transition-opacity group-hover:opacity-40">
                         <Zap size={64} className="text-primary" />
                      </div>
                      <h3 className="text-2xl font-bold text-primary mb-2">{omenResult.type}</h3>
                      <p className="text-lg text-white leading-relaxed">{omenResult.description}</p>
                   </div>

                   <div className="grid grid-cols-2 gap-4">
                      <div className="p-4 rounded-2xl bg-white/5 border border-white/10">
                         <p className="text-xs text-muted-foreground uppercase mb-1">SCI Impact</p>
                         <p className={`text-xl font-mono ${omenResult.sci_modifier >= 0 ? 'text-blue-400' : 'text-red-400'}`}>
                            {omenResult.sci_modifier >= 0 ? '+' : ''}{omenResult.sci_modifier.toFixed(2)}
                         </p>
                      </div>
                      <div className="p-4 rounded-2xl bg-white/5 border border-white/10">
                         <p className="text-xs text-muted-foreground uppercase mb-1">Entropy delta</p>
                         <p className={`text-xl font-mono ${omenResult.entropy_modifier >= 0 ? 'text-purple-400' : 'text-green-400'}`}>
                            {omenResult.entropy_modifier >= 0 ? '+' : ''}{omenResult.entropy_modifier.toFixed(2)}
                         </p>
                      </div>
                   </div>

                   <button className="w-full py-3 rounded-2xl bg-white/5 hover:bg-white/10 border border-white/10 text-white font-semibold flex items-center justify-center gap-2 transition-all">
                      <Send size={18} /> Inject into Simulation
                   </button>
                </motion.div>
              ) : (
                <div className="h-[400px] flex flex-col items-center justify-center text-center space-y-4 opacity-50">
                   <div className="w-20 h-20 rounded-full bg-white/5 border border-dashed border-white/20 flex items-center justify-center">
                      <Sparkles size={32} className="text-muted-foreground" />
                   </div>
                   <p className="text-sm max-w-[200px]">Perform a causal weave to manifest a potential Omen.</p>
                </div>
              )}
           </ObserverPanel>
        </div>
      </div>
    </div>
  );
}

import { redirect } from "next/navigation";
import { getObserverUniverseSummariesServer } from "@/modules/observer/api";

export default async function UniversesPage() {
  // If there's only one universe, we could redirect, but the user wants a connected dashboard.
  // For now, let's redirect to the dashboard hub which shows all universes anyway.
  redirect("/dashboard");
}

'use client';

import React, { useMemo, useCallback } from 'react';
import {
  ReactFlow,
  Background,
  Controls,
  Panel,
  useNodesState,
  useEdgesState,
  MarkerType,
  Node,
  Edge,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';
import type { ChronicleRecord } from '@/store/useSimulationStore';

interface CausalGraphProps {
  chronicles: ChronicleRecord[];
}

const CausalGraph = ({ chronicles }: CausalGraphProps) => {
  // Chuyển đổi Chronicles thành Nodes và Edges cho React Flow
  const initialNodes: Node[] = useMemo(() => {
    return chronicles.map((c, idx) => {
      // Try to extract loom data from raw_payload if available
      let headline = c.title || `Event ${idx + 1}`;
      let slogan = "The story blooms...";
      
      try {
        const raw = typeof c.raw_payload === 'string' ? JSON.parse(c.raw_payload) : c.raw_payload;
        if (raw?.loom_result?.news_headline) headline = raw.loom_result.news_headline;
        if (raw?.loom_result?.news_slogan) slogan = raw.loom_result.news_slogan;
      } catch (e) {}

      return {
        id: c.id?.toString() || idx.toString(),
        data: { 
          label: (
            <div className="flex flex-col gap-1">
              <span className="font-bold text-[9px] text-primary/90">{headline}</span>
              <span className="text-[7px] text-white/50 italic">"{slogan}"</span>
            </div>
          )
        },
        position: { x: idx * 250, y: 100 + (idx % 2) * 100 },
        style: {
          background: 'rgba(30, 30, 30, 0.85)',
          color: '#fff',
          border: '1px solid rgba(255, 255, 255, 0.15)',
          borderRadius: '16px',
          fontSize: '10px',
          width: 200,
          padding: '12px',
          backdropFilter: 'blur(12px)',
          boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.37)',
        },
      };
    });
  }, [chronicles]);

  const initialEdges: Edge[] = useMemo(() => {
    const edges: Edge[] = [];
    for (let i = 0; i < initialNodes.length - 1; i++) {
      edges.push({
        id: `e${i}-${i + 1}`,
        source: initialNodes[i].id,
        target: initialNodes[i + 1].id,
        label: 'leads to',
        animated: true,
        style: { stroke: '#6366f1' },
        labelStyle: { fill: '#818cf8', fontSize: 8, fontWeight: 700 },
        markerEnd: {
          type: MarkerType.ArrowClosed,
          color: '#6366f1',
        },
      });
    }
    return edges;
  }, [initialNodes]);

  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);

  return (
    <section className="h-full w-full rounded-[28px] border border-white/10 bg-card/45 backdrop-blur-xl overflow-hidden relative">
      <div className="absolute top-6 left-6 z-10 pointer-events-none">
        <p className="text-[10px] uppercase tracking-[0.28em] text-primary/70">Causal Graph</p>
        <h2 className="mt-2 text-xl font-semibold tracking-tight text-white">Narrative influence chain</h2>
      </div>

      <div className="h-full w-full mt-12">
        {chronicles.length > 0 ? (
          <ReactFlow
            nodes={nodes}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            fitView
            colorMode="dark"
          >
            <Background color="#333" gap={20} />
            <Controls />
            <Panel position="bottom-right" className="bg-background/50 p-2 rounded-lg border border-white/10 backdrop-blur-md">
              <p className="text-[8px] text-muted-foreground">Interactive Causal Projection v2</p>
            </Panel>
          </ReactFlow>
        ) : (
          <div className="flex h-full items-center justify-center p-12">
            <div className="rounded-2xl border border-dashed border-white/10 bg-background/25 p-8 text-center">
              <p className="text-sm text-muted-foreground">No chronicle nodes available for graph projection.</p>
              <p className="mt-2 text-[10px] text-muted-foreground/50 italic">Wait for the simulation to bloom...</p>
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

export default CausalGraph;

'use client';

import React from 'react';
import { motion } from 'framer-motion';
import { Radio, Mic2, Zap, Share2, Activity } from 'lucide-react';

interface MediaStationPanelProps {
  activeNarrative: any;
  onClose?: () => void;
}

const MediaStationPanel = ({ activeNarrative, onClose }: MediaStationPanelProps) => {
  if (!activeNarrative) return null;

  return (
    <motion.div
      initial={{ x: 400, opacity: 0 }}
      animate={{ x: 0, opacity: 1 }}
      exit={{ x: 400, opacity: 0 }}
