'use client';

import React, { useMemo } from 'react';
import { motion } from 'framer-motion';

interface RealityPulseProps {
  entropy: number;
  stability: number;
  tick?: number;
  size?: number;
}

/**
 * RealityPulse (V4.1): Quantum-stabilized Visualization with Pulse Sync.
 */
export function RealityPulse({ entropy, stability, tick = 0, size = 140 }: RealityPulseProps) {
  // Movement State based on tick change
  const [lastTick, setLastTick] = React.useState(tick);
  const [pulseActive, setPulseActive] = React.useState(false);

  React.useEffect(() => {
    if (tick !== lastTick) {
      setLastTick(tick);
      setPulseActive(true);
      const timer = setTimeout(() => setPulseActive(false), 600);
      return () => clearTimeout(timer);
    }
  }, [tick, lastTick]);

  // Pressure (0 to 1): Synthesis of chaos
  const pressure = useMemo(() => {
    return Math.max(0, Math.min(1, entropy * (1.1 - stability) * 1.2));
  }, [entropy, stability]);

  // Dynamic values
  const primaryColor = pressure > 0.8 ? '#e11d48' : pressure > 0.4 ? '#d97706' : '#0284c7';
  const pulseDuration = Math.max(0.3, 1.8 - pressure * 1.4);
  const turbulenceFrequency = 0.015 + pressure * 0.06;

  return (
    <div 
      className="relative flex items-center justify-center p-4 group"
      style={{ width: size, height: size }}
    >
      {/* Background Quantum Aura */}
      <motion.div
        animate={{
          scale: [1, 1.3 + pressure * 0.4, 1],
          opacity: [0.1, 0.25 + pressure * 0.15, 0.1],
        }}
        transition={{
          repeat: Infinity,
          duration: pulseDuration * 2,
          ease: "linear",
        }}
        className="absolute inset-0 rounded-full blur-[40px]"
        style={{ backgroundColor: primaryColor }}
      />

      <svg width={size} height={size} viewBox="0 0 100 100" className="relative z-10 overflow-visible">
        <defs>
          {/* Quantum Turbulence Filter */}
          <filter id="quantumTurbulence" x="-20%" y="-20%" width="140%" height="140%">
            <feTurbulence 
              type="fractalNoise" 
              baseFrequency={turbulenceFrequency} 
              numOctaves="3" 
              result="noise" 
            >
              <animate 
                attributeName="baseFrequency" 
                values={`${turbulenceFrequency}; ${turbulenceFrequency * 1.5}; ${turbulenceFrequency}`} 
                dur={`${pulseDuration * 4}s`} 
                repeatCount="indefinite" 
              />
            </feTurbulence>
            <feDisplacementMap in="SourceGraphic" in2="noise" scale={10 + pressure * 20} />
          </filter>

          <radialGradient id="quantumCore" cx="50%" cy="50%" r="50%">
            <stop offset="0%" stopColor="#fff" />
            <stop offset="30%" stopColor={primaryColor} />
            <stop offset="100%" stopColor="transparent" strokeOpacity="0" />
          </radialGradient>
        </defs>

        {/* Outer Orbital Rings */}
        {[0, 1, 2].map((i) => (
          <motion.circle
            key={i}
            cx="50"
            cy="50"
            r={30 + i * 10}
            fill="none"
            stroke={primaryColor}
            strokeWidth="0.5"
            strokeOpacity={0.15 - i * 0.03}
            strokeDasharray="4 8"
            animate={{ rotate: 360 * (i % 2 === 0 ? 1 : -1) }}
            transition={{ repeat: Infinity, duration: 15 + i * 5, ease: "linear" }}
          />
        ))}

        {/* The Distorted Core */}
        <motion.g filter="url(#quantumTurbulence)">
          {/* Fractal geometry (Triangles) */}
          {[0, 120, 240].map((angle, i) => (
            <motion.path
                key={i}
                d="M 50 20 L 80 70 L 20 70 Z"
                fill="none"
                stroke={primaryColor}
                strokeWidth="1.5"
                strokeOpacity={0.5 + (1-i*0.1)}
                initial={{ rotate: angle, scale: 0.8 }}
                style={{ transformOrigin: '50% 50%' }}
                animate={{
                  rotate: angle + 360,
                  scale: pulseActive ? [1, 1.4, 1] : [0.8, 1 + pressure * 0.2, 0.8],
                  strokeOpacity: [0.35, 0.7, 0.35],
                }}
                transition={{
                  repeat: pulseActive ? 0 : Infinity,
                  duration: pulseActive ? 0.6 : pulseDuration * 5,
                  ease: "easeInOut",
                  delay: i * 0.2,
                }}
              />
          ))}

          {/* Core Singularity */}
          <motion.circle
            cx="50"
            cy="50"
            r={12 + pressure * 15}
            fill="url(#quantumCore)"
            animate={{
              scale: pulseActive ? [1, 1.6, 1] : [1, 1.2, 1],
              opacity: pulseActive ? [0.8, 1, 0.8] : [0.8, 1, 0.8]
            }}
            transition={{
              repeat: pulseActive ? 0 : Infinity,
              duration: pulseActive ? 0.4 : pulseDuration,
              ease: "easeInOut",
            }}
          />
        </motion.g>

        {/* Atmospheric Chaos (Dust/Particles) */}
        {pressure > 0.3 && [...Array(8)].map((_, i) => (
          <motion.circle
            key={i}
            cx={50 + Math.cos(i) * 35}
            cy={50 + Math.sin(i) * 35}
            r={0.5 + Math.random()}
            fill={primaryColor}
            animate={{
              x: [0, (Math.random() - 0.5) * 20],
              y: [0, (Math.random() - 0.5) * 20],
              opacity: [0, 0.8, 0]
            }}
            transition={{
              repeat: Infinity,
              duration: 2 + Math.random() * 2,
              delay: i * 0.3
            }}
          />
        ))}

        {/* Scanning Line (High Stability) */}
        {stability > 0.8 && (
           <motion.line 
             x1="10" y1="50" x2="90" y2="50" 
             stroke="currentColor" strokeWidth="0.5" strokeOpacity="0.2"
             className="text-primary"
             animate={{ y1: [30, 70, 30], y2: [30, 70, 30] }}
             transition={{ repeat: Infinity, duration: 4, ease: "easeInOut" }}
           />
        )}
      </svg>

      {/* HUD Info */}
      <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none translate-y-2">
         <motion.span 
           animate={{ 
             opacity: pulseActive ? 1 : [0.4, 0.8, 0.4],
             scale: pulseActive ? 1.2 : 1
           }}
           className={`font-display text-[9px] tracking-[0.2em] uppercase ${pulseActive ? 'text-primary' : 'text-slate-500'}`}
         >
            {pulseActive ? 'ĐỒNG BỘ PULSE' : pressure > 0.7 ? 'BIẾN BIẾN CAUSAL' : 'KHÓA REALITY'}
         </motion.span>
         <span className="font-mono text-xs font-bold text-slate-900 drop-shadow-[0_0_8px_rgba(14,165,233,0.3)]">
            {Math.round(stability * 100)}%
         </span>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Zap, ChevronRight, Play, FastForward, SkipForward, Power } from 'lucide-react';
import { useAdvanceUniverseMutation } from '@/modules/observer/api';
import { toast } from 'sonner';

interface SimulationControlFABProps {
  universeId: string;
}

const SimulationControlFAB = ({ universeId }: SimulationControlFABProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const advanceMutation = useAdvanceUniverseMutation(universeId);

  const pulseSimulation = async (ticks: number) => {
    try {
      await advanceMutation.mutateAsync(ticks);
      toast.success(`XUNG NHÂN QUẢ THÀNH CÔNG: +${ticks} NHỊP`, {
        icon: <Zap size={14} className="text-sky-500" />,
        className: "bg-white border-sky-200 text-sky-600 font-sans text-xs uppercase font-black shadow-lg",
      });
      setIsOpen(false);
    } catch (error) {
      toast.error('PHÁT HIỆN LỖI TIẾN TRÌNH NHÂN QUẢ', {
        className: "bg-white border-rose-200 text-rose-600 font-sans text-xs uppercase font-black shadow-lg",
      });
    }
  };

  const pulseOptions = [
    { label: 'Xung Delta', ticks: 1, icon: Play, desc: '+1 VÉC-TƠ NHỊP' },
    { label: 'Xung Macro', ticks: 5, icon: FastForward, desc: '+5 VÉC-TƠ NHỊP' },
    { label: 'Bùng nổ Kỳ dị', ticks: 10, icon: SkipForward, desc: '+10 VÉC-TƠ NHỊP' },
  ];

  return (
    <div className="fixed bottom-8 right-8 z-[100] flex flex-col items-end gap-3 font-sans">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
            className="mb-4 flex flex-col gap-2 p-2 rounded-[2rem] bg-white border border-slate-200 shadow-2xl overflow-hidden min-w-[280px]"
          >
            <div className="px-5 py-4 border-b border-slate-100 mb-2 flex items-center justify-between">
               <span className="text-[10px] font-black uppercase tracking-[0.25em] text-slate-300">Ghi đè Nhân quả Thủ công</span>
               <div className="w-2 h-2 rounded-full bg-sky-500/40 animate-pulse" />
            </div>
            {pulseOptions.map((opt) => (
              <button
                key={opt.ticks}
                onClick={() => pulseSimulation(opt.ticks)}
                disabled={advanceMutation.isPending}
                className="group flex items-center gap-5 px-5 py-4 rounded-2xl hover:bg-slate-50 transition-all text-left disabled:opacity-50"
              >
                <div className="w-12 h-12 rounded-xl bg-sky-50 border border-sky-100 flex items-center justify-center text-sky-600 group-hover:bg-sky-600 group-hover:text-white transition-all shadow-sm">
                  <opt.icon size={20} />
                </div>
                <div className="flex-1">
                  <p className="text-[11px] font-black text-slate-900 uppercase tracking-wider">{opt.label}</p>
                  <p className="text-[9px] text-slate-400 uppercase font-black italic mt-1">{opt.desc}</p>
                </div>
                <ChevronRight size={16} className="text-slate-200 group-hover:text-sky-500 transition-all" />
              </button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>

      <motion.button
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        onClick={() => setIsOpen(!isOpen)}
        className={`
          relative w-20 h-20 rounded-full flex items-center justify-center shadow-2xl transition-all duration-500
          ${isOpen ? 'bg-sky-500 rotate-[135deg] shadow-sky-500/25' : 'bg-white border-2 border-slate-100 text-sky-600'}
          ${advanceMutation.isPending ? 'animate-pulse' : ''}
          hover:shadow-sky-500/20 active:scale-90
        `}
      >
        <div className="absolute inset-0 rounded-full bg-sky-500/10 animate-ping pointer-events-none" />
        
        {isOpen ? (
           <Power size={32} className="text-white" />
        ) : (
           <Zap size={32} className="text-sky-600" />
        )}
        
        {advanceMutation.isPending && (
           <svg className="absolute inset-0 w-full h-full -rotate-90">
              <circle
                cx="40"
                cy="40"
                r="38"
                fill="none"
                stroke="currentColor"
                strokeWidth="3"
                strokeDasharray="239"
                className="text-sky-500 animate-dash"
              />
           </svg>
        )}
      </motion.button>
    </div>
  );
};

export default SimulationControlFAB;

'use client';

import { useObserverActorDecisions, useObserverActorDetail, useObserverActorEvents } from '@/modules/observer/api';
import { ObserverEmptyState } from '@/modules/observer/components/ObserverEmptyState';
import { ObserverErrorState } from '@/modules/observer/components/ObserverErrorState';
import { ObserverLoadingState } from '@/modules/observer/components/ObserverLoadingState';
import { ObserverPanel } from '@/modules/observer/components/ObserverPanel';
import type { ActorDecision, ActorDetail, ActorEventEntry } from '@/modules/observer/types';
import { HUDCard, HUDBadge } from '@/modules/observer/components/ui/hud-primitives';

export function UniverseActorDetailClient({
  actorId,
  initialActor,
  initialEvents,
  initialDecisions,
}: {
  actorId: string;
  initialActor: ActorDetail;
  initialEvents: ActorEventEntry[];
  initialDecisions: ActorDecision[];
}) {
  const actorQuery = useObserverActorDetail(actorId, initialActor);
  const eventsQuery = useObserverActorEvents(actorId, initialEvents);
  const decisionsQuery = useObserverActorDecisions(actorId, initialDecisions);

  if (actorQuery.isError && !actorQuery.data) {
    return (
      <ObserverErrorState
        title="Thông tin thực thể hiện không khả dụng"
        description="Quan sát viên không thể tải hồ sơ thực thể hiện tại."
        onRetry={() => {
          void actorQuery.refetch();
        }}
      />
    );
  }

  if (!actorQuery.data) {
    return <ObserverLoadingState lines={3} />;
  }

  const actor = actorQuery.data;
  const visibleEvents = (eventsQuery.data ?? initialEvents).length > 0 ? eventsQuery.data ?? initialEvents : actor.recentEvents;
  const decisions = decisionsQuery.data ?? initialDecisions;
  const traitEntries = Object.entries(actor.traits).slice(0, 6);

  return (
    <div className="grid gap-8 2xl:grid-cols-[minmax(0,1.2fr)_minmax(400px,0.8fr)] font-sans">
      <div className="space-y-8">
        <ObserverPanel eyebrow="Hồ sơ Thực thể" title={actor.name}>
          <div className="space-y-6 text-sm leading-relaxed text-slate-500">
            <p className="font-medium text-slate-600 bg-slate-50 p-6 rounded-2xl border border-slate-100 italic">
              &ldquo;{actor.biography}&rdquo;
            </p>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm">
                <p className="text-[10px] font-black uppercase tracking-[0.25em] text-slate-300">Vai trò</p>
                <p className="mt-2 text-base font-black text-slate-900">{actor.role}</p>
              </div>
              <div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm">
                <p className="text-[10px] font-black uppercase tracking-[0.25em] text-slate-300">Khuynh hướng</p>
                <p className="mt-2 text-base font-black text-sky-600">{actor.alignment}</p>
              </div>
              <div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm">
                <p className="text-[10px] font-black uppercase tracking-[0.25em] text-slate-300">Giai đoạn Đời sống</p>
                <p className="mt-2 text-base font-black text-slate-900">{actor.lifeStage}</p>
              </div>
              <div className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm">
                <p className="text-[10px] font-black uppercase tracking-[0.25em] text-slate-300">Trạng thái</p>
                <div className="mt-2">
                  <HUDBadge color={actor.isAlive ? 'primary' : 'neutral'}>
                    {actor.isAlive ? 'Sống' : 'Ngừng hoạt động'}
                  </HUDBadge>
                </div>
              </div>
            </div>
          </div>
        </ObserverPanel>

        <ObserverPanel eyebrow="Vết tích Quyết định" title="Kết quả lập luận gần đây">
          {decisionsQuery.isLoading && decisions.length === 0 ? <ObserverLoadingState lines={3} /> : null}
          {decisionsQuery.isError && decisions.length === 0 ? (
            <ObserverErrorState
              title="Vết tích quyết định không khả dụng"
              description="Không thể làm mới lịch sử lập luận của thực thể."
              onRetry={() => {
                void decisionsQuery.refetch();
              }}
            />
          ) : null}
          {!decisionsQuery.isLoading && decisions.length === 0 ? (
            <ObserverEmptyState
              title="Chưa có vết tích quyết định"
              description="Thực thể này chưa công bố bất kỳ quyết định nào có thể truy xuất. Khi các dấu vết lập luận được lưu trữ, chúng sẽ xuất hiện ở đây cùng với điểm tin cậy và tiện ích."
            />
          ) : null}
          {decisions.length > 0 ? (
            <div className="space-y-4">
              {decisions.map((decision) => (
                <article key={decision.id} className="rounded-2xl border border-slate-100 bg-white p-6 shadow-sm hover:border-sky-200 transition-colors">
                  <div className="flex flex-wrap items-center justify-between gap-4 mb-3">
                    <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">{decision.actionType.replaceAll('_', ' ')}</h3>
                    <span className="text-[10px] font-black text-sky-600/60 bg-sky-50 px-2 py-0.5 rounded border border-sky-100">Nhịp {decision.tick.toLocaleString()}</span>
                  </div>
                  <p className="text-sm leading-relaxed text-slate-500 font-medium">{decision.summary}</p>
                  <div className="mt-4 flex flex-wrap gap-3">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-50 px-3 py-1 rounded-full border border-slate-100">
                      Độ tin cậy {(decision.confidence * 100).toFixed(0)}%
                    </span>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-50 px-3 py-1 rounded-full border border-slate-100">
                      Tiện ích {decision.utilityScore.toFixed(2)}
                    </span>
                  </div>
                </article>
              ))}
            </div>
          ) : null}
        </ObserverPanel>
      </div>

      <div className="space-y-8">
        <ObserverPanel eyebrow="Tầm ảnh hưởng" title="Trọng số quyết định và đặc điểm">
          <div className="rounded-3xl border border-sky-100 bg-sky-50 p-8 shadow-inner">
            <p className="text-5xl font-black text-sky-600 tracking-tighter">{actor.influence.toFixed(1)}</p>
            <p className="mt-3 text-xs font-bold text-sky-700/60 uppercase tracking-tight leading-relaxed">
              Điểm ảnh hưởng được suy ra từ các chỉ số thực thể, liên kết thực thể tối cao và áp lực quyết định.
            </p>
          </div>
          {traitEntries.length > 0 ? (
            <div className="mt-6 space-y-3">
              {traitEntries.map(([trait, value]) => (
                <div key={trait} className="flex items-center justify-between rounded-2xl border border-slate-100 bg-white px-5 py-4 shadow-sm">
                  <p className="text-xs font-black text-slate-500 uppercase tracking-widest">{trait.replaceAll('_', ' ')}</p>
                  <p className="text-sm font-black text-sky-600">{typeof value === 'number' ? value.toFixed(2) : String(value)}</p>
                </div>
              ))}
            </div>
          ) : null}
        </ObserverPanel>

        <ObserverPanel eyebrow="Sự kiện" title="Sự kiện đời sống gần đây">
          {eventsQuery.isLoading && visibleEvents.length === 0 ? <ObserverLoadingState lines={3} /> : null}
          {eventsQuery.isError && visibleEvents.length === 0 ? (
            <ObserverErrorState
              title="Sự kiện thực thể không khả dụng"
              description="Không thể làm mới dòng thời gian sự kiện của thực thể."
              onRetry={() => {
                void eventsQuery.refetch();
              }}
            />
          ) : null}
          {!eventsQuery.isLoading && visibleEvents.length === 0 ? (
            <ObserverEmptyState
              title="Chưa có sự kiện thực thể nào được ghi lại"
              description="Khi dòng thời gian thực thể khả dụng, bảng này sẽ hiển thị các sự kiện cột mốc giải thích vị thế và quyết định hiện tại."
            />
          ) : null}
          {visibleEvents.length > 0 ? (
            <div className="space-y-4">
              {visibleEvents.slice(0, 6).map((event) => (
                <article key={event.id} className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm hover:border-indigo-200 transition-colors">
                  <div className="flex items-center justify-between gap-4 mb-2">
                    <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">{event.type.replaceAll('_', ' ')}</h3>
                    <span className="text-[10px] font-black text-slate-300">Nhịp {event.tick.toLocaleString()}</span>
                  </div>
                  <p className="text-sm leading-relaxed text-slate-500 font-medium">{event.summary}</p>
                </article>
              ))}
            </div>
          ) : null}
        </ObserverPanel>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { useObserverUniverseActors } from '@/modules/observer/api';
import { ObserverEmptyState } from '@/modules/observer/components/ObserverEmptyState';
import { ObserverErrorState } from '@/modules/observer/components/ObserverErrorState';
import { ObserverLoadingState } from '@/modules/observer/components/ObserverLoadingState';
import { ObserverPanel } from '@/modules/observer/components/ObserverPanel';
import ActorDeepDiveSidebar from '@/modules/observer/components/ActorDeepDiveSidebar';
import type { ActorSummary, ActorDetail } from '@/modules/observer/types';
import { HUDCard, HUDBadge } from '@/modules/observer/components/ui/hud-primitives';
import { 
  Users, 
  Zap, 
  Activity, 
  ChevronRight, 
  Shield, 
  Target,
  Database,
  Search,
  Atom
} from 'lucide-react';



export function UniverseActorsClient({
  universeId,
  initialActors,
}: {
  universeId: string;
  initialActors: ActorSummary[];
}) {
  const [selectedActor, setSelectedActor] = useState<ActorDetail | null>(null);
  const actorsQuery = useObserverUniverseActors(universeId, initialActors);
  const actors = actorsQuery.data ?? initialActors;

  const handleActorClick = (summary: ActorSummary) => {
    setSelectedActor({
      ...summary,
      biography: `A key entity identified as ${summary.name}, operating in the role of ${summary.role}. Recent decisions indicate an alignment toward ${summary.alignment}.`,
      traits: {},
      metrics: { entropy: Math.random() * 0.5 + 0.2 },
      stats: {},
      capabilities: {},
      vitality: {},
      lifeStage: 'Adult',
      isAlive: true,
      birthTick: 0,
      deathTick: null,
      supremeEntity: null,
      recentEvents: []
    });
  };

  const totalInfluence = actors.reduce((sum, actor) => sum + actor.influence, 0);
  const averageInfluence = actors.length > 0 ? totalInfluence / actors.length : 0;

  return (
    <div className="space-y-8 max-w-7xl mx-auto p-4 md:p-6 font-mono">
      {/* HUD Stats Row */}
      <div className="grid gap-4 md:grid-cols-3">
        <HUDCard title="Cư dân Đang hoạt động" icon={Users}>
          <div className="flex items-baseline gap-2">
            <p className="text-3xl font-black text-slate-900">{actors.length}</p>
            <span className="text-[10px] text-slate-400 uppercase font-bold tracking-widest leading-none">Thực thể đã Đăng ký</span>
          </div>
        </HUDCard>
        <HUDCard title="Ảnh hưởng Trung bình" icon={Activity}>
          <div className="flex items-baseline gap-2">
            <p className="text-3xl font-black text-indigo-600">{averageInfluence.toFixed(1)}</p>
            <span className="text-[10px] text-indigo-300 uppercase font-bold tracking-widest leading-none">Hệ số Tác động</span>
          </div>
        </HUDCard>
        <HUDCard title="Nhịp Xung Nhân quả" icon={Zap} color="orange">
          <div className="space-y-2">
            <p className="text-[10px] font-bold text-orange-600 uppercase truncate">
               {actors[0]?.lastDecision ?? 'Không có dấu vết gần đây.'}
            </p>
            <div className="h-1 w-full bg-slate-100 rounded-full overflow-hidden">
               <div className="h-full bg-orange-500 w-[65%] animate-pulse" />
            </div>
          </div>
        </HUDCard>
      </div>

      {/* Main Actors List HUD */}
      <section className="space-y-6">
        <div className="flex items-center justify-between border-b border-slate-200 pb-4">
           <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-sky-50 border border-sky-100 shadow-sm">
                <Target className="w-5 h-5 text-sky-600" />
              </div>
              <h2 className="text-xl font-black text-slate-900 uppercase tracking-[0.3em]">Danh mục Thực thể</h2>
           </div>
           
           <div className="relative group">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 group-focus-within:text-sky-600 transition-colors" />
              <input 
                className="bg-slate-50 border border-slate-200 rounded-xl py-2 pl-10 pr-4 text-xs font-bold text-slate-700 focus:border-sky-400 focus:bg-white outline-none w-64 transition-all shadow-inner"
                placeholder="ĐANG QUÉT CÁC THỰC THỂ..."
              />
           </div>
        </div>

        {actorsQuery.isLoading && actors.length === 0 ? <ObserverLoadingState lines={4} /> : null}
        
        {actorsQuery.isError && actors.length === 0 ? (
          <ObserverErrorState
            title="Không thể truy cập danh mục thực thể"
            description="Lớp thông tin không trả về dữ liệu thực thể cho nhánh này."
            onRetry={() => {
              void actorsQuery.refetch();
            }}
          />
        ) : null}

        {actors.length === 0 && !actorsQuery.isLoading ? (
          <div className="p-20 text-center border border-dashed border-slate-200 rounded-2xl bg-slate-50/50">
            <Atom className="w-12 h-12 text-slate-200 mx-auto mb-4 animate-spin-slow" />
            <p className="text-xs text-slate-400 uppercase tracking-[0.2em] font-bold">Không Phát hiện Chữ ký Sự sống nào</p>
            <div className="mt-8 flex justify-center gap-4">
               <Link href={`/universes/${universeId}/control`} className="px-4 py-2 border border-sky-200 bg-white text-sky-600 hover:bg-sky-50 text-[10px] font-bold uppercase transition-all rounded-lg shadow-sm">
                  Kích xung Cưỡng bức
               </Link>
            </div>
          </div>
        ) : (
          <div className="grid gap-4 xl:grid-cols-2 lg:grid-cols-2">
            {actors.map((actor) => (
              <button
                key={actor.id}
                onClick={() => handleActorClick(actor)}
                className="group relative block w-full text-left rounded-2xl border border-slate-200 bg-white p-5 transition-all hover:border-sky-300 hover:shadow-md overflow-hidden"
              >
                {/* Glow Effect on Hover */}
                <div className="absolute inset-x-0 bottom-0 h-[1.5px] bg-gradient-to-r from-transparent via-sky-500 to-transparent opacity-0 group-hover:opacity-100 transition-opacity" />
                
                <div className="flex items-start justify-between gap-4 relative z-10">
                  <div className="flex gap-4">
                    <div className="w-12 h-12 rounded-xl bg-slate-50 border border-slate-100 flex items-center justify-center group-hover:border-sky-200 transition-all shadow-sm">
                       <Users className="w-6 h-6 text-slate-300 group-hover:text-sky-600 group-hover:animate-pulse transition-all" />
                    </div>
                    <div>
                      <h3 className="text-md font-black text-slate-900 group-hover:text-sky-600 transition-colors uppercase tracking-tight">{actor.name}</h3>
                      <div className="flex items-center gap-2 mt-1">
                        <HUDBadge color="primary" className="text-[8px] py-0 border-sky-100">{actor.role}</HUDBadge>
                        <span className="text-[9px] text-slate-400 uppercase font-bold tracking-tighter">{actor.alignment}</span>
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    <div className="text-[8px] text-slate-400 uppercase font-bold tracking-widest mb-1">Mức độ Ảnh hưởng</div>
                    <div className="text-lg font-black text-slate-900 font-mono italic">{actor.influence.toFixed(1)}</div>
                  </div>
                </div>
                
                <div className="mt-6 p-3 rounded-xl bg-slate-50 border border-slate-100 text-[11px] leading-relaxed text-slate-600 italic group-hover:text-slate-700 transition-colors">
                  <span className="text-sky-600 font-bold mr-2">NHẬT KÝ:</span>
                  "{actor.lastDecision}"
                </div>
                
                <div className="mt-4 flex items-center justify-between text-[9px] font-bold text-slate-400 uppercase">
                   <div className="flex items-center gap-4">
                      <span className="flex items-center gap-1 group-hover:text-sky-600 transition-colors"><Database size={12} /> ID: {actor.id.slice(0, 8)}</span>
                      <span className="flex items-center gap-1"><Shield size={12} /> XÁC THỰC: THÀNH CÔNG</span>
                   </div>
                   <div className="flex items-center gap-1 text-sky-600 opacity-0 group-hover:opacity-100 transition-opacity font-black">
                      CHI TIẾT <ChevronRight size={12} />
                   </div>
                </div>
              </button>
            ))}
          </div>
        )}
      </section>

      <ActorDeepDiveSidebar 
        actor={selectedActor} 
        onClose={() => setSelectedActor(null)} 
      />
    </div>
  );
}

import Link from "next/link";
import type { UniverseSummary } from "@/modules/observer/types";
import { 
  Activity, 
  Zap, 
  ShieldCheck, 
  Globe, 
  GitBranch, 
  ShieldAlert,
  ChevronRight,
  Terminal
} from "lucide-react";
import { HUDBadge } from "./ui/hud-primitives";
import { HUD_TOKENS } from "./ui/design-tokens";

const statusConfig: Record<UniverseSummary["status"], { color: "primary" | "secondary" | "destructive" | "neutral", label: string }> = {
  active: { color: "primary", label: "ỔN ĐỊNH" },
  paused: { color: "neutral", label: "TẠM DỪNG" },
  forked: { color: "secondary", label: "PHÂN KỲ" },
};

export function UniverseCard({ universe }: { universe: UniverseSummary }) {
  const config = statusConfig[universe.status];

  return (
    <Link
      href={`/universes/${universe.id}`}
      className="group relative block rounded-[2.5rem] border border-slate-200 bg-white p-8 transition-all hover:border-sky-400 hover:shadow-2xl hover:-translate-y-1 overflow-hidden"
    >
      {/* HUD Accent Line */}
      <div className={`absolute top-0 left-0 w-1.5 h-full ${config.color === 'primary' ? 'bg-sky-500' : config.color === 'secondary' ? 'bg-indigo-500' : 'bg-slate-300'} opacity-20 group-hover:opacity-100 transition-opacity`} />
      
      <div className="flex items-start justify-between gap-6 mb-8 relative z-10">
        <div>
          <div className="flex items-center gap-2.5 mb-3">
            <Terminal className="w-3.5 h-3.5 text-slate-300" />
            <span className={HUD_TOKENS.text_hud_badge + " text-slate-300"}>Nút_Thực_tại</span>
          </div>
          <h2 className="text-3xl font-black text-slate-900 uppercase tracking-tighter group-hover:text-sky-600 transition-colors italic">
            {universe.name}
          </h2>
        </div>
        <HUDBadge color={config.color}>
          {config.label}
        </HUDBadge>
      </div>

      <p className="text-[12px] font-bold leading-relaxed text-slate-400 uppercase tracking-tight mb-10 line-clamp-2 italic">
        {universe.focus}
      </p>

      <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
        <Metric label="Nhịp" value={`#${universe.currentTick ?? 0}`} icon={Activity} />
        <Metric label="Kỷ nguyên" value={universe.era ?? 'Genesis'} icon={Globe} />
        <Metric label="Độ ổn định" value={`${(universe.stability ?? 0).toFixed(1)}%`} icon={ShieldCheck} />
        <Metric label="Hỗn loạn" value={(universe.entropy ?? 0).toFixed(3)} icon={Zap} />
        <Metric label="Nhánh" value={String(universe.branchCount ?? 0)} icon={GitBranch} />
        <Metric label="Dị biệt" value={String(universe.anomalyCount ?? 0)} icon={ShieldAlert} status="destructive" />
      </div>
      
      <div className="mt-8 flex items-center justify-between text-[10px] font-black text-slate-200 uppercase border-t border-slate-100 pt-6">
         <span className="font-sans">Mã_Xác_thực: {(universe.id ?? '').slice(0, 12)}</span>
         <div className="flex items-center gap-2 text-sky-500 opacity-0 group-hover:opacity-100 transition-all translate-x-4 group-hover:translate-x-0">
            KHỞI TẠO <ChevronRight size={14} />
         </div>
      </div>
    </Link>
  );
}

function Metric({ label, value, icon: Icon, status = "default" }: { label: string; value: string; icon: any; status?: "default" | "destructive" }) {
  return (
    <div className={HUD_TOKENS.metric_box + " hover:bg-white transition-all shadow-inner hover:shadow-sm"}>
      <div className="flex items-center gap-2.5 mb-2.5">
        <Icon className={`w-3.5 h-3.5 ${status === 'destructive' ? 'text-rose-500' : 'text-slate-300'}`} />
        <span className={HUD_TOKENS.text_hud_badge + " text-slate-300"}>{label}</span>
      </div>
      <p className={`text-sm font-black ${status === 'destructive' ? 'text-rose-600' : 'text-slate-700'} truncate`}>
        {value}
      </p>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Atom, 
  Users, 
  ScrollText, 
  Globe, 
  Zap, 
  Database,
  Layers,
  ChevronRight,
  Activity
} from 'lucide-react';
import { useQuery } from '@tanstack/react-query';
import { fetchClientJson } from '@/shared/api/observer-http';
import { HUDCard, HUDBadge, HUDProgress, DataValue } from '@/modules/observer/components/ui/hud-primitives';
import { useObserverUniverseRealtime } from '@/modules/observer/useObserverUniverseRealtime';
import { HUD_TOKENS } from '@/modules/observer/components/ui/design-tokens';
import { RealityCore, VfxConfig } from '@/modules/observer/components/RealityCore';
import type { UniverseDetail } from '@/modules/observer/types';

interface RealityState {
  universe_id: number;
  tick: number;
  era: string;
  pulse: {
    entropy: number;
    stability_index: number;
    entropy_threshold: number;
    collapse_probability: number;
  };
  layers: {
    physical: any;
    life: any;
    social: any;
    narrative: any;
  };
  materials: any[];
  civilization: {
    complexity: number;
    knowledge_nodes: number;
    settlements: any[];
  };
  vfx_config: VfxConfig;
}

export default function UniverseRealityStateClient({ 
  universeId 
}: { 
  universeId: string 
}) {
  const [activeLayer, setActiveLayer] = useState<'physical' | 'social' | 'narrative'>('physical');
  
  // Tích hợp Real-time: Lắng nghe sự kiện từ Centrifugo để tự động Invalidate Cache
  const { connectionState } = useObserverUniverseRealtime(universeId);

  // Chuyển sang React Query: Quản lý cache và trạng thái đồng bộ hoàn hảo
  const { data: state, isLoading, isError } = useQuery({
    queryKey: ['observer', 'universe', universeId, 'reality-state'],
    queryFn: () => fetchClientJson<RealityState>(`/api/worldos/universes/${universeId}/reality-state`),
    refetchOnWindowFocus: false,
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <motion.div 
          animate={{ rotate: 360 }}
          transition={{ duration: 2, repeat: Infinity, ease: "linear" }}
        >
          <Atom className="w-12 h-12 text-sky-500 opacity-50" />
        </motion.div>
      </div>
    );
  }

  if (isError || !state) {
    return (
      <div className="p-12 text-center rounded-[2.5rem] border-2 border-dashed border-rose-200 bg-rose-50/30">
        <Activity className="w-12 h-12 text-rose-300 mx-auto mb-4" />
        <p className={HUD_TOKENS.text_hud_label}>Mất liên kết thực tại lượng tử</p>
      </div>
    );
  }

  const layerLabels: Record<string, string> = {
    physical: 'VẬT LÝ',
    social: 'XÃ HỘI',
    narrative: 'TỰ SỰ'
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto p-4 md:p-8">
      {/* HUD Header */}
      <header className={HUD_TOKENS.section_header}>
        <div className="space-y-1">
          <div className="flex items-center gap-3">
            <Atom className="w-10 h-10 text-sky-600" />
            <h1 className={HUD_TOKENS.text_hud_title}>
              Người quan sát <span className="text-sky-500/50">v6.2</span>
            </h1>
          </div>
          <p className={HUD_TOKENS.text_hud_label}>
            ID: <span className="text-sky-600">#{universeId}</span> | 
            LINK: <span className={connectionState === 'connected' ? "text-emerald-500 animate-pulse" : "text-amber-500"}>
              {connectionState.toUpperCase()}
            </span>
          </p>
        </div>
        <div className="flex gap-6 bg-slate-50 p-5 rounded-2xl border border-slate-200 shadow-sm">
          <DataValue label="Tick" value={state.tick} unit="τ" />
          <div className="w-px h-10 bg-slate-200" />
          <DataValue label="Độ phức tạp" value={state.civilization.complexity} unit="Ω" />
        </div>
      </header>

      {/* Main Bento Grid */}
      <div className={HUD_TOKENS.bento_grid}>
        
        {/* Reality Core 3D Viewer (VFX Đa Kỷ nguyên) */}
        <div className="md:col-span-2 lg:col-span-3 lg:row-span-2 space-y-6">
          <RealityCore 
            pulse={{
              universeId,
              tick: state.tick,
              entropy: state.pulse.entropy,
              entropyThreshold: state.pulse.entropy_threshold,
              stabilityIndex: state.pulse.stability_index,
              collapseProbability: state.pulse.collapse_probability,
              informationDensity: 1.0, 
              informationalMass: 1.0,
              singularityRisk: 'none',
              activeAttractor: 'none',
              lastMutationVector: null,
              mutationHistorySize: 0
            }} 
            era={state.era} 
            vfxConfig={state.vfx_config}
          />
          
          <HUDCard 
            title="Sơ đồ Lớp thực tại" 
            icon={Layers} 
            className="flex-1"
          >
            <div className="flex flex-col gap-4">
              {(['narrative', 'social', 'physical'] as const).map((layer, idx) => (
                <motion.button
                  key={layer}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: idx * 0.1 }}
                  onClick={() => setActiveLayer(layer)}
                  className={`relative w-full p-4 rounded-xl border transition-all duration-300 ${
                    activeLayer === layer 
                    ? 'bg-sky-50 border-sky-300 shadow-sm' 
                    : 'bg-white border-slate-100 hover:border-sky-200'
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div className={`p-2 rounded-lg ${
                        layer === 'physical' ? 'bg-emerald-50 text-emerald-600' :
                        layer === 'social' ? 'bg-sky-50 text-sky-600' :
                        'bg-indigo-50 text-indigo-600'
                      }`}>
                        {layer === 'physical' ? <Globe className="w-5 h-5" /> :
                         layer === 'social' ? <Users className="w-5 h-5" /> :
                         <ScrollText className="w-5 h-5" />}
                      </div>
                      <span className="font-bold text-sm uppercase tracking-wider text-slate-800">{layerLabels[layer]}</span>
                    </div>
                    {activeLayer === layer && <ChevronRight className="w-4 h-4 text-sky-500" />}
                  </div>
                </motion.button>
              ))}
            </div>
          </HUDCard>
        </div>

        {/* Vital Signs */}
        <HUDCard title="Chỉ số Văn minh" icon={Zap}>
          <div className="space-y-6 pt-2">
            <div className="space-y-3">
              <div className="flex justify-between">
                <span className={HUD_TOKENS.text_hud_label}>Độ phức tạp</span>
                <span className="text-sky-600 font-black italic">{state.civilization.complexity.toFixed(4)}</span>
              </div>
              <HUDProgress value={Math.min(100, state.civilization.complexity * 10)} />
            </div>
            
            <div className="grid grid-cols-2 gap-4 pt-4">
              <div className={HUD_TOKENS.metric_box}>
                <span className={HUD_TOKENS.text_hud_label}>NÚT TRÍ TUỆ</span>
                <span className={HUD_TOKENS.text_hud_value}>{state.civilization.knowledge_nodes}</span>
              </div>
              <div className={HUD_TOKENS.metric_box}>
                <span className={HUD_TOKENS.text_hud_label}>ĐIỂM TỤ TẬP</span>
                <span className={HUD_TOKENS.text_hud_value}>{state.civilization.settlements.length}</span>
              </div>
            </div>
          </div>
        </HUDCard>

        {/* Materials List */}
        <HUDCard title="Bản thể học Vật chất" icon={Database}>
          <div className="p-0 max-h-[250px] overflow-y-auto pr-2 custom-scrollbar space-y-5">
            {state.materials.map((cat: any) => (
              <div key={cat.ontology} className="space-y-3">
                <div className="flex justify-between items-center bg-sky-50 px-3 py-1.5 rounded-xl">
                  <span className="text-[10px] font-black uppercase text-sky-700">{cat.ontology}</span>
                  <span className="text-[9px] bg-sky-500 text-white px-2 py-0.5 rounded-full font-black">{cat.count} UNIT</span>
                </div>
                <div className="grid gap-2">
                  {cat.items.slice(0, 4).map((item: any) => (
                    <div key={item.id} className="text-xs p-3 bg-slate-50 hover:bg-sky-50 rounded-xl flex justify-between items-center border border-slate-100 group transition-all">
                      <span className="text-slate-700 font-black">{item.name}</span>
                      <span className="font-black text-sky-600 bg-white px-2 py-0.5 rounded shadow-sm">{(item.current_value ?? 0).toFixed(1)}</span>
                    </div>
                  ))}
                </div>
              </div>
            ))}
          </div>
        </HUDCard>

        {/* Layer Analysis Detail */}
        <AnimatePresence mode="wait">
          <motion.div
            key={activeLayer}
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -30 }}
            className="md:col-span-3 lg:col-span-4"
          >
            <HUDCard title={`Chẩn đoán Thực tại: ${layerLabels[activeLayer]}`} icon={Activity}>
              <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-6 py-4">
                {(Object.entries(state.layers[activeLayer] || {})).map(([key, value]: [string, any], idx) => (
                  <motion.div 
                    key={key} 
                    initial={{ opacity: 0 }} 
                    animate={{ opacity: 1 }} 
                    transition={{ delay: idx * 0.05 }}
                    className={HUD_TOKENS.metric_box}
                  >
                    <span className={HUD_TOKENS.text_hud_label}>{key.replace(/_/g, ' ')}</span>
                    <span className={HUD_TOKENS.text_hud_value}>
                       {typeof value === 'number' ? value.toFixed(2) : Array.isArray(value) ? value.length : 'OK'}
                    </span>
                  </motion.div>
                ))}
              </div>

              {activeLayer === 'social' && (
                <div className="mt-8 space-y-6 border-t-2 border-slate-50 pt-8">
                  <div className="flex items-center gap-3">
                    <div className="w-1.5 h-1.5 rounded-full bg-sky-500 animate-pulse" />
                    <h4 className={HUD_TOKENS.text_hud_label}>Tập hợp Xã hội phát hiện</h4>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-6">
                    {state.civilization.settlements.map((s: any, i: number) => (
                      <div key={i} className="p-5 rounded-2xl border border-slate-100 bg-white shadow-sm hover:border-sky-300 hover:shadow-md transition-all group overflow-hidden">
                        <div className="flex justify-between items-start mb-4">
                          <span className="font-black text-slate-900 text-sm">{s.name}</span>
                          <HUDBadge color="primary">{s.population} POP</HUDBadge>
                        </div>
                        <HUDProgress value={(s.stability || 0.5) * 100} />
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </HUDCard>
          </motion.div>
        </AnimatePresence>

      </div>
    </div>
  );
}

'use client';

import Link from 'next/link';
import { useObserverUniverseSnapshots } from '@/modules/observer/api';
import { ObserverEmptyState } from '@/modules/observer/components/ObserverEmptyState';
import { ObserverErrorState } from '@/modules/observer/components/ObserverErrorState';
import { ObserverLoadingState } from '@/modules/observer/components/ObserverLoadingState';
import { ObserverPanel } from '@/modules/observer/components/ObserverPanel';
import type { SnapshotSummary } from '@/modules/observer/types';

export function UniverseSnapshotsClient({
  universeId,
  initialSnapshots,
}: {
  universeId: string;
  initialSnapshots: SnapshotSummary[];
}) {
  const snapshotsQuery = useObserverUniverseSnapshots(universeId, initialSnapshots);
  const snapshots = snapshotsQuery.data ?? initialSnapshots;

  return (
    <ObserverPanel eyebrow="Ảnh chụp Trạng thái" title="Các điểm kiểm tra lưu trữ trạng thái">
      {snapshotsQuery.isLoading && snapshots.length === 0 ? <ObserverLoadingState lines={3} /> : null}
      {snapshotsQuery.isError && snapshots.length === 0 ? (
        <ObserverErrorState
          title="Ảnh chụp trạng thái không khả dụng"
          description="Người quan sát không thể làm mới các ảnh chụp điểm kiểm tra cho nhánh này."
          onRetry={() => {
            void snapshotsQuery.refetch();
          }}
        />
      ) : null}
      {!snapshotsQuery.isLoading && snapshots.length === 0 ? (
        <ObserverEmptyState
          title="Chưa có ảnh chụp trạng thái nào được ghi lại"
          description="Nhánh này chưa công bố ảnh chụp điểm kiểm tra nào. Hãy ghi lại một ảnh từ bảng điều khiển để tạo tham chiếu ổn định cho các nhánh và kiểm tra trong tương lai."
          action={
            <Link href={`/universes/${universeId}/control`} className="rounded-xl border border-sky-200 bg-sky-50 px-4 py-2 text-xs font-bold text-sky-700 transition hover:bg-sky-100 shadow-sm">
              Tạo từ bảng điều khiển
            </Link>
          }
        />
      ) : null}
      {snapshots.length > 0 ? (
        <div className="space-y-4">
          {snapshots.map((snapshot) => (
            <article key={snapshot.id} className="rounded-2xl border border-slate-100 bg-white p-5 shadow-sm hover:shadow-md transition-shadow">
              <div className="flex flex-wrap items-center justify-between gap-4">
                <div>
                  <h3 className="text-base font-black text-slate-900">{snapshot.label}</h3>
                  <p className="mt-1 text-xs font-bold text-slate-400">{snapshot.capturedAt}</p>
                </div>
                <span className="text-[10px] font-black text-sky-600 bg-sky-50 px-2 py-1 rounded border border-sky-100">TICK {snapshot.tick.toLocaleString()}</span>
              </div>
              <p className="mt-3 text-[13px] leading-6 text-slate-600 italic">"{snapshot.note}"</p>
              <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-4">
                <div className="rounded-xl border border-slate-100 bg-slate-50 px-4 py-3 shadow-inner">
                  <p className="text-[10px] uppercase font-bold tracking-widest text-slate-400">Entropy</p>
                  <p className="mt-1 text-lg font-black text-rose-600">{(snapshot.entropy ?? 0).toFixed(3)}</p>
                </div>
                <div className="rounded-xl border border-slate-100 bg-slate-50 px-4 py-3 shadow-inner">
                  <p className="text-[10px] uppercase font-bold tracking-widest text-slate-400">Độ ổn định</p>
                  <p className="mt-1 text-lg font-black text-indigo-600">{(snapshot.stabilityIndex ?? 0).toFixed(3)}</p>
                </div>
                {Object.entries(snapshot.metrics)
                  .slice(0, 2)
                  .map(([key, value]) => (
                    <div key={key} className="rounded-xl border border-slate-100 bg-slate-50 px-4 py-3 shadow-inner">
                      <p className="text-[10px] uppercase font-bold tracking-widest text-slate-400 capitalize">{key}</p>
                      <p className="mt-1 text-lg font-black text-sky-600">{typeof value === 'number' ? (value ?? 0).toFixed(2) : String(value)}</p>
                    </div>
                  ))}
              </div>
            </article>
          ))}
        </div>
      ) : null}
    </ObserverPanel>
  );
}

'use client';

import React from 'react';
import Link from 'next/link';
import { useSearchParams } from 'next/navigation';
import { 
  useObserverAutonomyAudit, 
  useObserverUniverseChronicles, 
  useObserverUniverseForks, 
  useObserverUniverseSnapshots, 
  useObserverUniverseTimeline 
} from '@/modules/observer/api';
import type { AutonomyAudit } from '@/modules/observer/contracts';
import { ObserverEmptyState } from '@/modules/observer/components/ObserverEmptyState';
import { ObserverErrorState } from '@/modules/observer/components/ObserverErrorState';
import { ObserverLoadingState } from '@/modules/observer/components/ObserverLoadingState';
import { ObserverPanel } from '@/modules/observer/components/ObserverPanel';
import type { BranchSummary, ChronicleEntry, SnapshotSummary, TimelineEvent } from '@/modules/observer/types';
import { HUDCard, HUDBadge } from '@/modules/observer/components/ui/hud-primitives';
import { 
  History, 
  Zap, 
  GitBranch, 
  Layers, 
  Clock, 
  Activity, 
  ChevronRight,
  Database,
  ShieldAlert,
  ArrowRightCircle,
  Shield
} from 'lucide-react';



function laneClass(highlighted: boolean) {
  return highlighted ? 'border-sky-300 bg-sky-50 shadow-[0_0_15px_rgba(14,165,233,0.1)]' : 'border-slate-200 bg-white shadow-sm';
}

export function UniverseTimelineClient({
  universeId,
  initialTimeline,
  initialChronicles,
  initialSnapshots,
  initialForks,
  initialAutonomyAudit,
}: {
  universeId: string;
  initialTimeline: TimelineEvent[];
  initialChronicles: ChronicleEntry[];
  initialSnapshots: SnapshotSummary[];
  initialForks: BranchSummary[];
  initialAutonomyAudit?: AutonomyAudit;
}) {
  const searchParams = useSearchParams();
  const focusedTick = Number(searchParams.get('tick') ?? '');
  const timelineQuery = useObserverUniverseTimeline(universeId, initialTimeline);
  const chroniclesQuery = useObserverUniverseChronicles(universeId, initialChronicles);
  const snapshotsQuery = useObserverUniverseSnapshots(universeId, initialSnapshots);
  const forksQuery = useObserverUniverseForks(universeId, initialForks);
  const auditQuery = useObserverAutonomyAudit(universeId, initialAutonomyAudit);

  const timeline = timelineQuery.data ?? initialTimeline;
  const chronicles = chroniclesQuery.data ?? initialChronicles;
  const snapshots = snapshotsQuery.data ?? initialSnapshots;
  const forks = forksQuery.data ?? initialForks;
  const mutations = auditQuery.data?.chronicle ?? [];

  const interventions = [
    ...snapshots.map((snapshot) => ({ id: `snapshot-${snapshot.id}`, kind: 'Snapshot', tick: snapshot.tick, label: snapshot.label, summary: snapshot.note })),
    ...forks.map((fork) => ({ id: `fork-${fork.id}`, kind: 'Fork', tick: fork.divergenceTick, label: fork.label, summary: `Branch ${fork.status} now tracks tick ${fork.currentTick}.` })),
  ].sort((left, right) => right.tick - left.tick);

  const mutationLane = mutations
    .map((entry) => ({
      id: entry.dslHash,
      tick: entry.latestTick ?? -1,
      label: entry.dslPath ?? entry.dslHash,
      summary: entry.vector ?? entry.source,
      timestamp: entry.latestTimestamp,
      versionCount: entry.versionCount,
    }))
    .sort((left, right) => right.tick - left.tick);

  return (
    <div className="space-y-8 max-w-[1600px] mx-auto p-4 md:p-6 font-mono">
      {/* Main Timeline Control HUD */}
      <section className="relative grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="absolute -inset-2 bg-primary/5 blur-3xl pointer-events-none" />
        
        {/* Lane 1: Causal Stream */}
        <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-2">
              <Activity className="w-5 h-5 text-sky-600" />
              <h2 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900">Luồng Nhân Quả</h2>
            </div>
            <HUDBadge color="primary">Hoạt động</HUDBadge>
          </div>
          <div className="space-y-3 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
            {timelineQuery.isLoading && timeline.length === 0 ? <ObserverLoadingState lines={4} /> : null}
            {timelineQuery.isError && timeline.length === 0 ? (
              <ObserverErrorState title="Lỗi Đồng bộ" description="Liên kết lượng tử bị gián đoạn." onRetry={() => void timelineQuery.refetch()} />
            ) : null}
            {timeline.length === 0 && !timelineQuery.isLoading && (
              <div className="p-8 text-center text-[10px] text-slate-400 uppercase tracking-widest border border-dashed border-slate-200 rounded-lg">Đang chờ luồng nhân quả...</div>
            )}
            {timeline.map((entry) => {
              const highlighted = Number.isFinite(focusedTick) && entry.tick === focusedTick;
              return (
                <article key={entry.id} className={`relative rounded-lg border p-4 transition-all duration-300 ${laneClass(highlighted)} group hover:border-sky-300`}>
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-[10px] text-sky-600 font-bold tracking-tighter">TIC-{entry.tick.toString().padStart(6, '0')}</span>
                    <HUDBadge color="primary" className="text-[8px] border-sky-200">{entry.category}</HUDBadge>
                  </div>
                  <p className="text-[11px] leading-relaxed text-slate-600 line-clamp-3 italic">"{entry.summary}"</p>
                  <div className="mt-4 pt-3 border-t border-slate-100 flex items-center justify-between">
                    <span className="text-[9px] text-slate-400 truncate max-w-[100px]">{entry.zone}</span>
                    <Link href={`/universes/${universeId}/chronicles?tick=${entry.tick}`} className="flex items-center gap-1 text-[9px] text-sky-600 font-bold hover:text-sky-700 transition-colors">
                      <History className="w-3 h-3" /> PHÂN TÍCH
                    </Link>
                  </div>
                </article>
              );
            })}
          </div>
        </div>

        {/* Lane 2: Intervention Layer */}
        <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-2">
              <Shield className="w-5 h-5 text-indigo-600" />
              <h2 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900">Sự Can Thiệp</h2>
            </div>
            <HUDBadge color="secondary">An toàn</HUDBadge>
          </div>
          <div className="space-y-3 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
            {interventions.map((entry) => {
              const highlighted = Number.isFinite(focusedTick) && entry.tick === focusedTick;
              return (
                <article key={entry.id} className={`rounded-lg border p-4 transition-all ${laneClass(highlighted)} border-indigo-100 bg-indigo-50/50 hover:bg-indigo-50`}>
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-[10px] text-indigo-600/60 font-bold">TIC-{entry.tick.toString().padStart(6, '0')}</span>
                    <span className="text-[9px] font-black text-indigo-600 px-1 bg-indigo-100 rounded">{entry.kind}</span>
                  </div>
                  <h3 className="text-xs font-bold text-slate-900 mb-2 uppercase">{entry.label}</h3>
                  <p className="text-[11px] text-slate-500 leading-relaxed mb-4">{entry.summary}</p>
                  <Link href={`/universes/${universeId}/control`} className="inline-flex items-center gap-2 text-[9px] text-indigo-600 font-bold hover:underline">
                    <Database size={12} /> TRUY XUẤT TRẠNG THÁI
                  </Link>
                </article>
              );
            })}
            {interventions.length === 0 && <div className="p-8 text-center text-[10px] text-slate-400 uppercase tracking-widest border border-dashed border-slate-200 rounded-lg">Đang chờ sự can thiệp...</div>}
          </div>
        </div>

        {/* Lane 3: Mutation Log */}
        <div className="space-y-4">
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-2">
              <Zap className="w-5 h-5 text-orange-600" />
              <h2 className="text-sm font-black uppercase tracking-[0.2em] text-slate-900">Nhật Ký Đột Biến</h2>
            </div>
            <HUDBadge color="orange">Không ổn định</HUDBadge>
          </div>
          <div className="space-y-3 max-h-[70vh] overflow-y-auto pr-2 custom-scrollbar">
            {mutationLane.map((entry) => {
              const highlighted = Number.isFinite(focusedTick) && entry.tick === focusedTick;
              return (
                <article key={entry.id} className={`rounded-lg border p-4 transition-all ${laneClass(highlighted)} border-orange-200 bg-orange-50/50 hover:bg-orange-50`}>
                  <div className="flex items-center justify-between mb-2">
                     <span className="text-[10px] text-orange-600/60 font-bold italic">
                       {entry.tick < 0 ? 'ĐANG ĐỒNG BỘ' : `TIC-${entry.tick.toString().padStart(6, '0')}`}
                     </span>
                     <div className="flex items-center gap-2">
                        <span className="text-[9px] text-orange-600 font-bold bg-orange-100 px-1 rounded">v{entry.versionCount}</span>
                        <ShieldAlert className="w-3 h-3 text-orange-600 animate-pulse" />
                     </div>
                  </div>
                  <h3 className="text-xs font-bold text-slate-900 mb-1 truncate">{entry.label}</h3>
                  <p className="text-[10px] text-slate-400 font-mono mb-4 break-all opacity-70">{entry.id}</p>
                  <div className="flex items-center justify-between">
                    <span className="text-[8px] text-slate-400 uppercase font-bold">{entry.timestamp ? new Date(entry.timestamp).toLocaleTimeString() : 'Không rõ thời gian'}</span>
                    <Link href={`/universes/${universeId}/control`} className="text-[9px] text-orange-600 hover:text-orange-700 font-bold">
                      KIỂM TRA ĐỘT BIẾN
                    </Link>
                  </div>
                </article>
              );
            })}
            {mutationLane.length === 0 && <div className="p-8 text-center text-[10px] text-slate-400 uppercase tracking-widest border border-dashed border-slate-200 rounded-lg">Đang chờ quá trình tự tạo...</div>}
          </div>
        </div>
      </section>

      {/* Narrative Synthesis HUD */}
      <section className="mt-12 space-y-6">
        <div className="flex items-center gap-3 border-b border-slate-200 pb-4">
           <Layers className="w-6 h-6 text-sky-600" />
           <h2 className="text-xl font-black text-slate-900 uppercase tracking-[0.3em]">Tổng Hợp Tự Sự</h2>
        </div>
        
        {chronicles.length === 0 && !chroniclesQuery.isLoading ? (
          <div className="p-12 text-center border border-dashed border-slate-200 rounded-2xl bg-slate-50/50">
            <p className="text-xs text-slate-400 uppercase tracking-widest font-bold">Đang khởi tạo các mảnh biên niên sử...</p>
          </div>
        ) : (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {chronicles.slice(0, 9).map((entry) => (
              <HUDCard key={entry.id} title={entry.title} color="primary" className="hover:scale-[1.02] transition-transform">
                <p className="text-xs leading-relaxed text-slate-600 mb-6 italic">"{entry.summary}"</p>
                <div className="flex justify-between items-center mt-auto border-t border-slate-100 pt-3">
                  <HUDBadge color="primary" className="text-[8px] border-sky-100">Mã tham chiếu: {entry.id.slice(0, 8)}</HUDBadge>
                  <Link href={`/universes/${universeId}/timeline?tick=${entry.tick}`} className="text-[9px] font-bold text-sky-600 hover:underline flex items-center gap-1">
                    ĐẾN TICK <ArrowRightCircle size={10} />
                  </Link>
                </div>
              </HUDCard>
            ))}
          </div>
        )}
      </section>

      <style jsx global>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 4px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: rgba(15, 23, 42, 0.02);
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: rgba(14, 165, 233, 0.2);
          border-radius: 2px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: rgba(14, 165, 233, 0.4);
        }
      `}</style>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Globe, 
  Search, 
  Atom, 
  BookOpen, 
  Users, 
  Zap, 
  Info,
  ChevronRight,
  Sparkles,
  History,
  Map,
  Lightbulb,
  Activity,
  GitBranch,
  ExternalLink,
  Clock,
  Layers
} from 'lucide-react';
import Link from 'next/link';
import { useObserverUniverseSummaries, useObserverRealityPulse, useObserverUniverseTimeline } from '@/modules/observer/api';
import AutoLinkContent from './wiki/AutoLinkContent';
import { fetchClientJson } from '@/shared/api/observer-http';
import { HUDCard, HUDBadge, HUDProgress } from '@/modules/observer/components/ui/hud-primitives';


interface WikiSearchResult {
  actors: any[];
  chronicles: any[];
  axioms: any[];
}

export default function WikiPortalClient({ universeId }: { universeId: string }) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<WikiSearchResult | null>(null);
  const [activeAxioms, setActiveAxioms] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const pulseQuery = useObserverRealityPulse(universeId);
  const timelineQuery = useObserverUniverseTimeline(universeId, []);

  useEffect(() => {
    const fetchAxioms = async () => {
      try {
        const data = await fetchClientJson<any>('/api/wiki/axioms');
        setActiveAxioms(data.data || []);
      } catch (e) {
        console.error("Failed to fetch axioms", e);
      }
    };
    fetchAxioms();
  }, []);

  const handleSearch = async (val: string) => {
    setQuery(val);
    if (val.length < 2) {
      setResults(null);
      return;
    }
    setLoading(true);
    try {
      const data = await fetchClientJson<any>(`/api/wiki/${universeId}/search?q=${val}`);
      setResults(data.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const categories = [
    { id: 'axioms', name: 'Kho Định đề', icon: <Atom className="w-5 h-5" />, description: 'Quy luật & Hằng số vật lý' },
    { id: 'entities', name: 'Thực thể Vũ trụ', icon: <Users className="w-5 h-5" />, description: 'Nhân vật, Chủng tộc & Tổ chức' },
    { id: 'chronicles', name: 'Đại Biên niên sử', icon: <History className="w-5 h-5" />, description: 'Biên niên sử & Chuỗi nhân quả' },
    { id: 'geography', name: 'Địa lý Vũ trụ', icon: <Map className="w-5 h-5" />, description: 'Địa lý đa vũ trụ & Vùng không gian' },
    { id: 'metaphysics', name: 'Siêu hình học', icon: <Lightbulb className="w-5 h-5" />, description: 'Khoa học, Đổi mới & Siêu hình' },
  ];

  return (
    <div className="space-y-12 max-w-7xl mx-auto p-4 md:p-8">
      {/* HUD Header Section */}
      <header className="relative py-12 text-center space-y-4 border-b border-slate-100">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,rgba(14,165,233,0.05),transparent)] pointer-events-none" />
        <motion.div
          initial={{ opacity: 0, scale: 0.8 }}
          animate={{ opacity: 1, scale: 1 }}
          className="inline-flex p-5 rounded-3xl bg-sky-50 border border-sky-100 mb-4 shadow-sm"
        >
          <BookOpen className="w-12 h-12 text-sky-600 animate-pulse" />
        </motion.div>
        <div>
          <h1 className="text-5xl font-black tracking-tighter text-slate-900 uppercase italic">
            Lưu trữ <span className="text-sky-500 italic">Bản thể</span> Đa vũ trụ
          </h1>
          <div className="flex items-center justify-center gap-6 mt-6">
             <div className="h-0.5 w-16 bg-gradient-to-r from-transparent to-sky-500/30" />
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">
               Bản ghi vĩnh cửu của Nhịp đập Thực tại #{universeId}
             </p>
             <div className="h-0.5 w-16 bg-gradient-to-l from-transparent to-sky-500/30" />
          </div>
        </div>
      </header>

      {/* Futuristic Search HUD */}
      <div className="relative max-w-3xl mx-auto group">
        <div className="absolute -inset-1 bg-gradient-to-r from-sky-500/20 to-indigo-500/20 rounded-2xl blur-lg opacity-40 group-hover:opacity-70 transition-opacity" />
        <div className="relative flex items-center bg-white border border-slate-200 rounded-2xl overflow-hidden focus-within:border-sky-500/50 focus-within:ring-4 focus-within:ring-sky-500/5 transition-all shadow-xl">
          <div className="pl-6 pointer-events-none">
            <Search className="w-7 h-7 text-slate-300 group-focus-within:text-sky-500 transition-colors" />
          </div>
          <input 
            className="w-full h-20 pl-5 pr-8 bg-transparent text-xl font-black text-slate-900 placeholder:text-slate-200 outline-none"
            placeholder="ĐANG QUÉT CÁC MẪU NHÂN QUẢ..."
            value={query}
            onChange={(e) => handleSearch(e.target.value)}
          />
          {loading && (
            <div className="pr-8">
              <motion.div animate={{ rotate: 360 }} transition={{ repeat: Infinity, duration: 1 }}>
                <Activity className="w-6 h-6 text-sky-500" />
              </motion.div>
            </div>
          )}
        </div>
        <div className="absolute -bottom-8 left-1/2 -translate-x-1/2 flex gap-6 text-[10px] font-black text-slate-300 uppercase tracking-widest">
           <span>Chỉ mục: 4,201,982 bản ghi</span>
           <span className="text-slate-100">|</span>
           <span>Độ trễ: 0.12ms</span>
        </div>
      </div>

      {/* Category Grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-6 pt-16">
        {categories.map((cat, idx) => (
          <motion.div
            key={cat.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: idx * 0.05 }}
          >
            <div className="group relative rounded-2xl border border-slate-100 bg-white p-8 flex flex-col items-center text-center gap-6 hover:border-sky-300 hover:shadow-lg transition-all cursor-pointer overflow-hidden">
               <div className="absolute inset-x-0 top-0 h-1 bg-sky-500 scale-x-0 group-hover:scale-x-100 transition-transform origin-left" />
               <div className="p-5 rounded-2xl bg-slate-50 text-slate-400 group-hover:text-sky-600 group-hover:bg-sky-50 transition-all duration-300 shadow-inner">
                 {cat.icon}
               </div>
               <div className="space-y-2">
                 <h3 className="font-black text-xs text-slate-800 group-hover:text-sky-700 transition-colors uppercase tracking-widest">{cat.name}</h3>
                 <p className="text-[10px] text-slate-400 font-bold uppercase leading-tight tracking-tight group-hover:text-slate-500">{cat.description}</p>
               </div>
            </div>
          </motion.div>
        ))}
      </div>

      <AnimatePresence>
        {results && (
          <motion.div
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 20 }}
            className="grid grid-cols-1 lg:grid-cols-3 gap-8 pt-16"
          >
            {/* Actors Results */}
            <HUDCard title="Cư dân được nhận diện" icon={Users}>
              <div className="space-y-2">
                {results.actors.map((actor: any) => (
                  <Link 
                    key={actor.id} 
                    href={`/universes/${universeId}/wiki/actor/${actor.id}`}
                    className="p-4 rounded-xl border border-transparent hover:border-sky-100 hover:bg-sky-50 transition-all flex items-center justify-between group"
                  >
                    <div>
                      <div className="font-black text-sm text-slate-800 group-hover:text-sky-700 transition-colors">{actor.name}</div>
                      <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{actor.role}</div>
                    </div>
                    <ChevronRight className="w-5 h-5 text-slate-200 group-hover:text-sky-500 transition-colors" />
                  </Link>
                ))}
              </div>
            </HUDCard>

            {/* Chronicles Results */}
            <HUDCard title="Đồng bộ Biên niên sử" icon={History}>
              <div className="space-y-2">
                {results.chronicles.map((ch: any) => (
                  <div key={ch.id} className="p-4 rounded-xl border border-transparent hover:border-indigo-100 hover:bg-indigo-50 transition-all flex items-center justify-between group cursor-help">
                    <div className="flex-1">
                      <div className="font-black text-sm text-slate-800 truncate group-hover:text-indigo-700 transition-colors uppercase tracking-tight">{ch.title}</div>
                      <div className="flex items-center gap-3 mt-3">
                        <HUDBadge color="secondary">T-{ch.tick}</HUDBadge>
                        {ch.impact_score > 70 && <HUDBadge color="destructive">NGUY CẤP</HUDBadge>}
                      </div>
                    </div>
                    <div className="text-right">
                       <div className="text-[9px] text-slate-400 font-black tracking-widest mb-1">TÁC ĐỘNG</div>
                       <div className="text-sm font-black text-indigo-600">{ch.impact_score}%</div>
                    </div>
                  </div>
                ))}
              </div>
            </HUDCard>

            {/* Axioms Results */}
            <HUDCard title="Sổ đăng ký Định đề" icon={Atom}>
              <div className="space-y-2">
                {results.axioms.map((ax: any) => (
                  <Link 
                    key={ax.id} 
                    href={`/universes/${universeId}/wiki/axiom/${ax.id}`}
                    className="p-4 rounded-xl border border-transparent hover:border-emerald-100 hover:bg-emerald-50 transition-all flex items-center justify-between group"
                  >
                    <div className="flex-1">
                      <div className="font-black text-sm text-slate-800 group-hover:text-emerald-700 transition-colors uppercase">{ax.name}</div>
                      <div className="flex items-center gap-3 mt-2">
                        <span className="text-[10px] text-slate-400 font-bold italic truncate max-w-[120px]">{ax.id}</span>
                        {ax.drift_summary?.status === 'shifting' && (
                          <span className="flex items-center gap-1.5 text-[9px] text-orange-500 animate-pulse font-black uppercase tracking-widest">
                            <Zap className="w-3 h-3" /> Đã lệch
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="text-right flex flex-col items-end gap-2">
                       <HUDBadge className="text-[9px] border-emerald-100 text-emerald-600 bg-emerald-50 tracking-widest">{ax.dimension}</HUDBadge>
                       {ax.drift_summary && (
                         <div className={`text-xs font-black ${ax.drift_summary.drift > 0 ? 'text-emerald-600' : ax.drift_summary.drift < 0 ? 'text-rose-600' : 'text-slate-300'}`}>
                           {ax.drift_summary.drift > 0 ? '+' : ''}{(ax.drift_summary.drift ?? 0).toFixed(2)}
                         </div>
                       )}
                    </div>
                  </Link>
                ))}
              </div>
            </HUDCard>
          </motion.div>
        )}
      </AnimatePresence>

      {/* ── Tóm tắt trạng thái thế giới ── */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 pt-16">
        <HUDCard title="Giám sát Thực tại" icon={Globe}>
          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Độ hỗn loạn (Entropy)</span>
              <span className="text-sm font-black text-sky-600">{(pulseQuery.data?.entropy ?? 0).toFixed(3)}</span>
            </div>
            <HUDProgress value={(pulseQuery.data?.entropy ?? 0) * 100} color="primary" />
            <div className="flex justify-between items-center">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Độ ổn định</span>
              <span className="text-sm font-black text-indigo-600">{((pulseQuery.data?.stabilityIndex ?? 0) * 100).toFixed(1)}%</span>
            </div>
            <HUDProgress value={(pulseQuery.data?.stabilityIndex ?? 0) * 100} color="secondary" />
            <div className="flex justify-between items-center">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Rủi ro Điểm kỳ dị</span>
              <HUDBadge color={pulseQuery.data?.singularityRisk === 'HIGH' ? 'destructive' : 'neutral'}>
                {pulseQuery.data?.singularityRisk === 'HIGH' ? 'CAO' : (pulseQuery.data?.singularityRisk ?? 'N/A')}
              </HUDBadge>
            </div>
          </div>
        </HUDCard>

        <HUDCard title="Sự kiện gần đây" icon={Clock} className="md:col-span-2">
          <div className="space-y-3 max-h-[250px] overflow-y-auto custom-scrollbar pr-3">
            {(timelineQuery.data ?? []).slice(0, 5).map((event, idx) => (
              <div key={event.id ?? idx} className="flex items-start gap-4 p-4 rounded-xl border border-slate-50 hover:border-sky-100 hover:bg-sky-50/50 transition-all">
                <div className="flex-shrink-0 mt-2">
