export interface ObserverRealtimeState {
  connectionState: 'idle' | 'connecting' | 'connected' | 'disconnected';
  lastEventLabel: string | null;
}

export function useObserverUniverseRealtime(universeId: string): ObserverRealtimeState {
  const queryClient = useQueryClient();
  const clientRef = useRef<Centrifuge | null>(null);
  const [connectionState, setConnectionState] = useState<ObserverRealtimeState['connectionState']>('connecting');
  const [lastEventLabel, setLastEventLabel] = useState<string | null>(null);

  useEffect(() => {
    const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${proto}//${window.location.host}/connection/websocket`;
    const centrifuge = new Centrifuge(wsUrl, { token: '' });
    clientRef.current = centrifuge;

    const pulseSubscription = centrifuge.newSubscription(`universes.${universeId}`);
    pulseSubscription.on('publication', (ctx) => {
      // BINARY READY PROTOCOL (Hardfork 1.3)
      // Check if data is binary array (ArrayBuffer/Uint8Array)
      let payload: UniversePulsePublication = {};
      try {
        if (ctx.data instanceof Uint8Array || ctx.data instanceof ArrayBuffer) {
           // Trong tương lai, cắm thư viện MsgPack.decode(ctx.data) tại đây.
           // Hiện tại dùng TextDecoder làm phương án dự phòng cho UTF-8 raw byte.
           const decoder = new TextDecoder('utf-8');
           payload = JSON.parse(decoder.decode(ctx.data as BufferSource)) as UniversePulsePublication;
        } else if (typeof ctx.data === 'string') {
           payload = JSON.parse(ctx.data) as UniversePulsePublication;
        } else {
           payload = (ctx.data ?? {}) as UniversePulsePublication;
        }
      } catch (e) {
        console.warn('Centrifugo decoding error (expected binary/JSON):', e);
        payload = (ctx.data ?? {}) as UniversePulsePublication;
      }

      const tickLabel = typeof payload.tick === 'number' ? `Tick ${payload.tick.toLocaleString()}` : 'Universe pulse';
      setLastEventLabel(tickLabel);
      
      // Stage 4.3: Zero-Fetch Update. Không cần request lại HTTP, nạp thẳng vào cache.
      queryClient.setQueryData(['universes', universeId, 'realityPulse'], (old: any) => {
        return {
          ...old,
          ...payload,
          // Map fields from publication to RealityPulse if needed (they are already compatible)
        };
      });

      // Chỉ invalidate các phần khác không có trong Pulse nhị phân
      void queryClient.invalidateQueries({ queryKey: ['universes', universeId, 'metrics'] });
    });

    const mutationSubscription = centrifuge.newSubscription(`universes.${universeId}.autopoiesis`);
    mutationSubscription.on('publication', (ctx) => {
      const payload = (ctx.data ?? {}) as MutationPublication;
      const summary = payload.summary ?? {};
      const label = typeof summary.dsl_path === 'string' && summary.dsl_path.length > 0 ? summary.dsl_path : 'mutated rule pack';
      setLastEventLabel(`Autopoiesis touched ${label}`);
      toast.message('Autopoiesis mutation applied', {
        description: typeof summary.vector === 'string' && summary.vector.length > 0 ? summary.vector : `Observer detected a live rule mutation on ${label}.`,
      });
      void invalidateObserverUniverseQueries(queryClient, universeId, ['realityPulse', 'autonomyAudit', 'timeline']);
    });

    centrifuge.on('connecting', () => setConnectionState('connecting'));
    centrifuge.on('connected', () => setConnectionState('connected'));
    centrifuge.on('disconnected', () => setConnectionState('disconnected'));

    pulseSubscription.subscribe();
    mutationSubscription.subscribe();
    centrifuge.connect();

    return () => {
      pulseSubscription.unsubscribe();
      mutationSubscription.unsubscribe();
      centrifuge.disconnect();
      clientRef.current = null;
      setConnectionState('disconnected');
    };
  }, [queryClient, universeId]);

  return { connectionState, lastEventLabel };
}

import * as THREE from 'three';

let particles: { time: number; factor: number; speed: number; vec: THREE.Vector3 }[] = [];
let isReady = false;
const dummy = new THREE.Object3D();

// Worker context for Next.js
self.onmessage = (e: MessageEvent) => {
  const { type, payload } = e.data;

  if (type === 'INIT') {
    const { count } = payload;
    particles = [];
    for (let i = 0; i < count; i++) {
        const time = Math.random() * 100;
        const factor = 0.5 + Math.random() * 1.5;
        const speed = 0.005 + Math.random() / 200;
        
        // Quỹ đạo hình cầu xung quanh tâm
        const x = Math.random() * 2 - 1;
        const y = Math.random() * 2 - 1;
        const z = Math.random() * 2 - 1;
        const vec = new THREE.Vector3(x, y, z).normalize().multiplyScalar(2.0 + Math.random() * 2.5);
        
        particles.push({ time, factor, speed, vec });
    }
    isReady = true;
    
    // Khởi tạo buffer đầu tiên và gửi lại Main Thread
    const initialBuffer = new ArrayBuffer(count * 16 * 4); // 16 floats (ma trận 4x4) * 4 bytes/float
    (self as any).postMessage({ type: 'INIT_DONE', buffer: initialBuffer }, [initialBuffer]);
  }

  if (type === 'TICK' && isReady) {
    const { buffer, era, entropy = 0, stabilityIndex = 1 } = payload;
    
    // Lấy view trên buffer nhận được từ Main Thread
    const view = new Float32Array(buffer);
    
    // Hệ số hỗn loạn dựa trên Entropy
    const chaos = Math.pow(entropy, 1.5) * 2.5;
    // Hệ số tập trung dựa trên Stability
    const gravity = Math.max(0.2, stabilityIndex);

    for (let i = 0; i < particles.length; i++) {
      const p = particles[i];
      // Tốc độ hạt tăng lên khi Entropy cao
      const speedMult = 1.0 + entropy * 2.0;
      const t = (p.time += p.speed * speedMult);

      // Quỹ đạo cơ bản bị ảnh hưởng bởi trọng lực (Stability)
      const currentRadius = p.vec.length() * (0.8 + (1.0 - gravity) * 0.5);
      const basePos = p.vec.clone().normalize().multiplyScalar(currentRadius);

      // Chuyển động nhiễu hỗn loạn (Chaos/Entropy Simulator)
      dummy.position.set(
        basePos.x + Math.cos(t * p.factor + i) * (0.1 + chaos),
        basePos.y + Math.sin(t * p.factor + i) * (0.1 + chaos),
        basePos.z + Math.cos(t * p.factor + i) * (0.1 + chaos)
      );

      // Góc xoay phụ thuộc vào kỷ nguyên và áp lực
      if (era === 'cyberpunk') {
        dummy.rotation.set(t * (2 + entropy), t * (2 + entropy), t * (2 + entropy));
      } else {
        dummy.lookAt(0, 0, 0);
      }

      // Kích thước hạt co giãn nhẹ theo nhịp đập
      const pulseScale = 1.0 + Math.sin(t * 2) * 0.1 * entropy;
      const baseSize = era === 'paleolithic' ? 0.06 : era === 'medieval' ? 0.04 : 0.03;
      const size = baseSize * pulseScale;
      dummy.scale.set(size, size, size);

      dummy.updateMatrix();

      // Nạp mảng số float của matrix (16 phần tử) trực tiếp vào buffer tại vị trí của particle i
      dummy.matrix.toArray(view, i * 16);
    }

    // Gửi trả buffer đã được tính toán xong về lại Main Thread.
    // Dùng Transferable Object (tham số 2: [view.buffer]) để cắt dứt hoàn toàn chi phí Copy Data.
    (self as any).postMessage({ type: 'TICK_DONE', buffer: view.buffer }, [view.buffer]);
  }
};

import { create } from "zustand";

export interface Universe {
  id: number;
  name: string;
  entropy: number;
  stability: number;
  status?: string;
  current_tick?: number;
}

export interface ChronicleRecord {
  id?: string | number;
  title?: string;
  content?: string;
  type?: string;
  raw_payload?: string | any;
}

export interface SimulationEntity {
  id: string | number;
  name?: string;
  weight?: number;
  vocation?: string;
  intent?: string;
}

export interface TransitionState {
  target: string;
  phase: number;
  startTick: number;
}

interface AdvancePayload {
  snapshot_tick?: number;
  universes?: Universe[];
  axioms?: Record<string, number>;
  chronicles?: ChronicleRecord[];
  entities?: SimulationEntity[];
  transition?: TransitionState;
  reality_strain?: number;
  anomaly_probability?: number;
  civilization_era?: string;
}

interface TransitionPayload {
  transition?: TransitionState;
  reality_strain?: number;
  anomaly_probability?: number;
}

interface SimulationState {
  currentTick: number;
  universes: Universe[];
  axioms: Record<string, number>;
  chronicles: ChronicleRecord[];
  entities: SimulationEntity[];
  isPaused: boolean;
  transition?: TransitionState;
  realityStrain: number;
  anomalyProbability: number;
  civilizationEra: string;
  updateFromAdvance: (data: AdvancePayload) => void;
  updateTransition: (data: TransitionPayload) => void;
  addChronicle: (chronicle: ChronicleRecord) => void;
  setUniverses: (universes: Universe[]) => void;
  togglePause: () => void;
}

export const useSimulationStore = create<SimulationState>((set) => ({
  currentTick: 0,
  universes: [],
  axioms: {},
  chronicles: [],
  entities: [],
  isPaused: false,
  realityStrain: 0,
  anomalyProbability: 0,
  civilizationEra: "Genesis",

  updateFromAdvance: (data) =>
    set((state) => ({
      currentTick: data.snapshot_tick ?? state.currentTick,
      universes: data.universes ?? state.universes,
      axioms: data.axioms ?? state.axioms,
      chronicles: data.chronicles ?? state.chronicles,
      entities: data.entities ?? state.entities,
      transition: data.transition ?? state.transition,
      realityStrain: data.reality_strain ?? state.realityStrain,
      anomalyProbability: data.anomaly_probability ?? state.anomalyProbability,
      civilizationEra: data.civilization_era ?? state.civilizationEra,
    })),

  updateTransition: (data) =>
    set((state) => ({
      transition: data.transition ?? state.transition,
      realityStrain: data.reality_strain ?? state.realityStrain,
      anomalyProbability: data.anomaly_probability ?? state.anomalyProbability,
    })),

  addChronicle: (chronicle) =>
    set((state) => ({
      chronicles: [chronicle, ...state.chronicles].slice(0, 50),
    })),

  setUniverses: (universes) => set({ universes }),

  togglePause: () => set((state) => ({ isPaused: !state.isPaused })),
}));
